// Regression test: "Order" (a real Forge AI domain entity, see
// domainEntities.ts) is a reserved SQL keyword. Before every table/column
// name in the generated server.js was double-quoted, `CREATE TABLE Order
// (...)` crashed the whole exported app at startup with a SQL syntax
// error -- caught not by the syntax-only checks above (esbuild/node --check
// both parse fine; this is a *runtime* SQL error) but by actually
// downloading, unzipping, npm-installing, and running a real export with an
// Order entity. This test reproduces that with a real child process and a
// real SQLite database, standing in for that manual check going forward.
test("generated server.js works end-to-end for an entity named after a reserved SQL keyword (e.g. Order)", async () => {
  const keywordProject: Project = {
    ...project,
    spec: {
      ...project.spec,
      entities: [
        {
          name: "Order",
          label: "Orders",
          fields: [
            { name: "customerName", label: "Customer", type: "text", required: true },
            { name: "group", label: "Group", type: "text", required: false }, // a column name that's also a keyword
          ],
        },
      ],
    },
  };
  const files = generateExportFiles(keywordProject);
  const serverJs = files.find((f) => f.path === "server.js")!.content;

  const dir = mkdtempSync(path.join(tmpdir(), "codegen-keyword-test-"));
  // The generated server.js imports "express" as a bare ESM specifier, which
  // (unlike CommonJS require) ignores NODE_PATH -- symlink this repo's
  // hoisted node_modules in instead of a slow real `npm install`.
  const repoRoot = path.resolve(import.meta.dirname, "../../..");
  symlinkSync(path.join(repoRoot, "node_modules"), path.join(dir, "node_modules"));
  writeFileSync(path.join(dir, "server.js"), serverJs);

  const port = 34000 + Math.floor(Math.random() * 5000);
  const child = spawn(process.execPath, ["--experimental-sqlite", "server.js"], {
    cwd: dir,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let stderr = "";
  child.stderr.on("data", (chunk) => {
    stderr += chunk.toString();
  });

  try {
    // Poll for the server to come up (or crash) instead of a fixed sleep.
    const deadline = Date.now() + 5000;
    let lastErr: unknown;
    while (Date.now() < deadline) {
      if (child.exitCode !== null) {
        throw new Error(`server.js exited early (code ${child.exitCode}):\n${stderr}`);
      }
      try {
        const res = await fetch(`http://localhost:${port}/api/Order`);
        assert.equal(res.status, 200);
        const body = await res.json();
        assert.deepEqual(body, { records: [] });

        // Also exercise the keyword column name end-to-end (create + read).
        const createRes = await fetch(`http://localhost:${port}/api/Order`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ customerName: "Dana", group: "VIP" }),
        });
        assert.equal(createRes.status, 201);
        const created = await createRes.json();
        assert.equal(created.record.group, "VIP");
        return;
      } catch (err) {
        lastErr = err;
        await new Promise((r) => setTimeout(r, 100));
      }
    }
    throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
  } finally {
    child.kill();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 1010: round 1006's own closing paragraph explicitly deferred
 * porting the live Forge AI preview's calendar subscription feed
 * (EntityPanel.tsx's "Subscribe" button, routes/calendar.ts,
 * calendarFeed.ts) to this exported standalone app -- confirmed still
 * missing as of round 1009 (`grep -n "feed\|Feed\|Subscribe"` across this
 * file and its own tests returned nothing calendar-related). Unlike the
 * live preview's own feed, this export needs no token: the whole exported
 * app has no authentication of any kind (every other /api/* route here is
 * already public), so the route only needs the entity name. Spawns a
 * real server.js (same pattern as the reserved-SQL-keyword test above),
 * creates a real record with a real date, and confirms the feed actually
 * serves a valid ICS calendar for it -- not just that the generated
 * source text looks right.
 */
test("generated server.js serves a real, working calendar subscription feed for an entity with a date field", async () => {
  const dealEntity: Entity = {
    name: "Deal",
    label: "Deals",
    fields: [
      { name: "title", label: "Title", type: "text", required: true },
      { name: "eventDate", label: "Event Date", type: "date", required: true },
    ],
  };
  const noDateEntity: Entity = {
    name: "Note",
    label: "Notes",
    fields: [{ name: "text", label: "Text", type: "text", required: true }],
  };
  const feedProject: Project = { ...project, spec: { ...project.spec, entities: [dealEntity, noDateEntity] } };
  const files = generateExportFiles(feedProject);
  const serverJs = files.find((f) => f.path === "server.js")!.content;

  const dir = mkdtempSync(path.join(tmpdir(), "codegen-feed-test-"));
  const repoRoot = path.resolve(import.meta.dirname, "../../..");
  symlinkSync(path.join(repoRoot, "node_modules"), path.join(dir, "node_modules"));
  writeFileSync(path.join(dir, "server.js"), serverJs);

  const port = 34000 + Math.floor(Math.random() * 5000);
  const child = spawn(process.execPath, ["--experimental-sqlite", "server.js"], {
    cwd: dir,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let stderr = "";
  child.stderr.on("data", (chunk) => {
    stderr += chunk.toString();
  });

  try {
    const deadline = Date.now() + 5000;
    let lastErr: unknown;
    while (Date.now() < deadline) {
      if (child.exitCode !== null) {
        throw new Error(`server.js exited early (code ${child.exitCode}):\n${stderr}`);
      }
      try {
        const createRes = await fetch(`http://localhost:${port}/api/Deal`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ title: "Trip to Eilat", eventDate: "2026-11-05" }),
        });
        assert.equal(createRes.status, 201);

        const feedRes = await fetch(`http://localhost:${port}/api/calendar/Deal.ics`);
        assert.equal(feedRes.status, 200, "a real date-bearing record must get a real feed, not a 404");
        assert.equal(feedRes.headers.get("content-type"), "text/calendar; charset=utf-8");
        const ics = await feedRes.text();
        assert.match(ics, /BEGIN:VCALENDAR/);
        assert.match(ics, /BEGIN:VEVENT/);
        assert.match(ics, /DTSTART;VALUE=DATE:20261105/);
        assert.match(ics, /SUMMARY:Trip to Eilat/);
        assert.match(ics, /END:VCALENDAR/);

        const noDateFeedRes = await fetch(`http://localhost:${port}/api/calendar/Note.ics`);
        assert.equal(noDateFeedRes.status, 404, "an entity with no date field at all must 404, not serve an always-empty feed");

        const missingEntityFeedRes = await fetch(`http://localhost:${port}/api/calendar/NoSuchEntity.ics`);
        assert.equal(missingEntityFeedRes.status, 404, "a nonexistent entity name must 404 too");
        return;
      } catch (err) {
        lastErr = err;
        await new Promise((r) => setTimeout(r, 100));
      }
    }
    throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
  } finally {
    child.kill();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 1034: DESCRIPTION parity with this exported app's own one-shot
 * "Export ICS" button (buildCalendarIcs) -- before this round the feed's
 * own VEVENTs carried only SUMMARY/DTSTART/DTEND. Spawns a real server.js
 * (same pattern as the round-1010 test above), creates a real Customer
 * record and a Deal record that points at it via a relation field, and
 * confirms the real feed route actually resolves that relation to the
 * Customer's own name in DESCRIPTION -- not a raw foreign-key id -- along
 * with an enum field's translated label.
 */
test("generated server.js's calendar feed DESCRIPTION resolves a relation field to its related record's real display label", async () => {
  const customerEntity: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [{ name: "fullName", label: "Full Name", type: "text", required: true }],
  };
  const dealEntity: Entity = {
    name: "Deal",
    label: "Deals",
    fields: [
      { name: "title", label: "Title", type: "text", required: true },
      { name: "eventDate", label: "Event Date", type: "date", required: true },
      { name: "stage", label: "Stage", type: "enum", required: true, enumValues: ["Open", "Won"], enumLabels: { Open: "פתוח", Won: "הצליח" } },
      { name: "customer", label: "Customer", type: "relation", relationTo: "Customer", required: false },
    ],
  };
  const feedProject: Project = { ...project, spec: { ...project.spec, entities: [customerEntity, dealEntity] } };
  const files = generateExportFiles(feedProject);
  const serverJs = files.find((f) => f.path === "server.js")!.content;

  const dir = mkdtempSync(path.join(tmpdir(), "codegen-feed-description-test-"));
  const repoRoot = path.resolve(import.meta.dirname, "../../..");
  symlinkSync(path.join(repoRoot, "node_modules"), path.join(dir, "node_modules"));
  writeFileSync(path.join(dir, "server.js"), serverJs);

  const port = 34000 + Math.floor(Math.random() * 5000);
  const child = spawn(process.execPath, ["--experimental-sqlite", "server.js"], {
    cwd: dir,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let stderr = "";
  child.stderr.on("data", (chunk) => {
    stderr += chunk.toString();
  });

  try {
    const deadline = Date.now() + 5000;
    let lastErr: unknown;
    while (Date.now() < deadline) {
      if (child.exitCode !== null) {
        throw new Error(`server.js exited early (code ${child.exitCode}):\n${stderr}`);
      }
      try {
        const customerRes = await fetch(`http://localhost:${port}/api/Customer`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ fullName: "Yossi Cohen" }),
        });
        assert.equal(customerRes.status, 201);
        const { record: customer } = (await customerRes.json()) as { record: { id: number } };

        const dealRes = await fetch(`http://localhost:${port}/api/Deal`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ title: "Trip to Eilat", eventDate: "2026-11-05", stage: "Won", customer: customer.id }),
        });
        assert.equal(dealRes.status, 201);

        const feedRes = await fetch(`http://localhost:${port}/api/calendar/Deal.ics`);
        assert.equal(feedRes.status, 200);
        const ics = await feedRes.text();
        assert.match(ics, /DESCRIPTION:/, "a record with non-empty description fields must get a DESCRIPTION line");
        const unfolded = ics.replace(/\r\n /g, "");
        assert.match(unfolded, /Customer: Yossi Cohen/, "the relation field must resolve to the related Customer's own real name, not a raw foreign-key id");
        assert.match(unfolded, /Stage: הצליח/, "the enum field must render its translated enumLabel, not the raw stored key");
        return;
      } catch (err) {
        lastErr = err;
        await new Promise((r) => setTimeout(r, 100));
      }
    }
    throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
  } finally {
    child.kill();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 1071: mirrors the live apps/api/src/calendarFeed.ts's own
 * identical round-1048 fix -- a `date` label field (reachable the same
 * way a boolean/enum label field already is: an entity with two+ date
 * fields and no name/title/text/longtext field) rendered the raw
 * unformatted "YYYY-MM-DD" string in this feed's own SUMMARY line instead
 * of a real formatted date. Round 1048's own sweep fixed codegen.ts's
 * other two chip-label copies (the one-shot export's own calendarLabelValue,
 * buildCalendarIcs's inline duplicate) but missed this feed route's own
 * copy entirely.
 */
test("generated server.js's calendar feed renders a date label field as a formatted date in SUMMARY, not the raw 'YYYY-MM-DD' string", async () => {
  const flightEntity: Entity = {
    name: "Flight",
    label: "Flights",
    fields: [
      { name: "departureDate", label: "Departure Date", type: "date", required: true },
      { name: "returnDate", label: "Return Date", type: "date", required: false },
    ],
  };
  const feedProject: Project = { ...project, spec: { ...project.spec, entities: [flightEntity] } };
  const files = generateExportFiles(feedProject);
  const serverJs = files.find((f) => f.path === "server.js")!.content;

  const dir = mkdtempSync(path.join(tmpdir(), "codegen-feed-date-label-test-"));
  const repoRoot = path.resolve(import.meta.dirname, "../../..");
  symlinkSync(path.join(repoRoot, "node_modules"), path.join(dir, "node_modules"));
  writeFileSync(path.join(dir, "server.js"), serverJs);

  const port = 34000 + Math.floor(Math.random() * 5000);
  const child = spawn(process.execPath, ["--experimental-sqlite", "server.js"], {
    cwd: dir,
    env: { ...process.env, PORT: String(port) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let stderr = "";
  child.stderr.on("data", (chunk) => {
    stderr += chunk.toString();
  });

  try {
    const deadline = Date.now() + 5000;
    let lastErr: unknown;
    while (Date.now() < deadline) {
      if (child.exitCode !== null) {
        throw new Error(`server.js exited early (code ${child.exitCode}):\n${stderr}`);
      }
      try {
        const createRes = await fetch(`http://localhost:${port}/api/Flight`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ departureDate: "2026-11-05", returnDate: "2026-11-12" }),
        });
        assert.equal(createRes.status, 201);

        const feedRes = await fetch(`http://localhost:${port}/api/calendar/Flight.ics`);
        assert.equal(feedRes.status, 200);
        const ics = await feedRes.text();
        assert.doesNotMatch(ics, /SUMMARY:2026-11-12/, "the date label field must never render as the raw unformatted ISO string");
        assert.match(ics, /SUMMARY:11\/12\/2026/, "the date label field must render as a real formatted date, matching toLocaleDateString()'s own output");
        return;
      } catch (err) {
        lastErr = err;
        await new Promise((r) => setTimeout(r, 100));
      }
    }
    throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
  } finally {
    child.kill();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 1072: a separate, previously-unaudited sibling of the SUMMARY fix
 * just above -- this feed's own DESCRIPTION resolves a RELATION field's
 * own target record to a display label via feedRecordDisplayLabel/
 * feedRelationDisplayLabel, not feedChipLabelValue. A join entity with no
 * name/title/text/enum field at all, only a date and a relation (e.g.
 * DailyLog { loggedAt: date, studentId: relation }), has
 * pickFeedDisplayField's own last-resort step land on the date field
 * regardless, and feedRecordDisplayLabel used to String() the raw
 * unformatted "YYYY-MM-DD" string as the related record's own label in
 * this feed's DESCRIPTION line.
 */
test("the generated server.js's own feedRecordDisplayLabel renders a date display field as a real formatted date, not the raw 'YYYY-MM-DD' string", () => {
  const serverJs = generateExportFiles(project).find((f) => f.path === "server.js")!.content;
  const feedDisplayFieldHintsSrc = serverJs.match(/const FEED_DISPLAY_FIELD_NAME_HINTS = .*;\n/)?.[0];
  const pickFeedDisplayFieldSrc = serverJs.match(/function pickFeedDisplayField\(entity\) \{[\s\S]*?\n\}\n/)?.[0];
  const feedRecordDisplayLabelSrc = serverJs.match(/function feedRecordDisplayLabel\(entity, record\) \{[\s\S]*?\n\}\n/)?.[0];
  const feedRelationDisplayLabelSrc = serverJs.match(/function feedRelationDisplayLabel\(field, value, recordIndexByEntity\) \{[\s\S]*?\n\}\n/)?.[0];
  const feedParseFieldDateSrc = serverJs.match(/function feedParseFieldDate\(raw\) \{[\s\S]*?\n\}\n/)?.[0];
  const feedFormatIcsDescriptionDateSrc = serverJs.match(/function feedFormatIcsDescriptionDate\(value\) \{[\s\S]*?\n\}\n/)?.[0];
  const dateFormatSrc = serverJs.match(/const DATE_FORMAT = .*;\n/)?.[0];
  assert.ok(
    feedDisplayFieldHintsSrc &&
      pickFeedDisplayFieldSrc &&
      feedRecordDisplayLabelSrc &&
      feedRelationDisplayLabelSrc &&
      feedParseFieldDateSrc &&
      feedFormatIcsDescriptionDateSrc &&
      dateFormatSrc,
    "expected to find FEED_DISPLAY_FIELD_NAME_HINTS/pickFeedDisplayField/feedRecordDisplayLabel/feedRelationDisplayLabel/feedParseFieldDate/feedFormatIcsDescriptionDate/DATE_FORMAT in generated server.js",
  );

  const dailyLogEntity = {
    name: "DailyLog",
    fields: [
      { name: "loggedAt", type: "date" },
      { name: "studentId", type: "relation", relationTo: "Student" },
    ],
  };
  const feedRelationDisplayLabel = new Function(
    "ENTITIES",
    `${dateFormatSrc}\n${feedParseFieldDateSrc}\n${feedFormatIcsDescriptionDateSrc}\n${feedDisplayFieldHintsSrc}\n${pickFeedDisplayFieldSrc}\n${feedRecordDisplayLabelSrc}\n${feedRelationDisplayLabelSrc}\nreturn feedRelationDisplayLabel;`,
  )([dailyLogEntity]);

  const logField = { name: "log", type: "relation", relationTo: "DailyLog" };
  assert.equal(
    feedRelationDisplayLabel(logField, 5, { DailyLog: new Map([[5, { id: 5, loggedAt: "2026-04-02", studentId: 2 }]]) }),
    "4/2/2026",
    "must render the date field as a real formatted date in the feed's own DESCRIPTION, not the raw ISO string",
  );
});

/**
 * Round 1010: the client-side half of the same gap -- confirms the
 * generated EntityView.jsx actually wires up the "Subscribe" button
 * (next to the existing one-shot Export ICS button) to copy the real
 * feed URL, with no token-fetch step (unlike the live preview's own
 * handleSubscribeCalendar), matching this export's own no-auth design.
 */
test("the exported EntityView wires up a calendar 'Subscribe' button next to the existing one-shot Export ICS button", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  assert.match(
    entityViewJsx,
    /async function handleSubscribeCalendar\(\)[\s\S]{0,300}navigator\.clipboard\.writeText\(url\)/,
    "expected handleSubscribeCalendar to copy a URL to the clipboard",
  );
  assert.match(
    entityViewJsx,
    /\/api\/calendar\/\$\{encodeURIComponent\(entity\.name\)\}\.ics/,
    "expected the copied URL to point at the new public feed route, with no token in it",
  );
  assert.match(
    entityViewJsx,
    /className="ics-subscribe-btn" onClick=\{handleSubscribeCalendar\}/,
    "expected a real Subscribe button wired to the real handler",
  );
});

/**
 * Round 802: the generated server.js's own README ("Extending it") tells
 * the user to add a field to ENTITIES and restart, promising "existing
 * columns are kept, and SQLite migrates new ones automatically (ALTER
 * TABLE, same as Forge AI's own migration engine)" -- but the schema loop
 * only ever ran CREATE TABLE IF NOT EXISTS, a documented no-op once the
 * table already exists (see packages/shared's own
 * findSanitizedIdentifierCollisions comment on this exact SQLite
 * semantics). A field added after the very first run was never actually
 * added to the real table, so every write touching it hit a raw,
 * untranslated SQLite error instead of the promised automatic migration.
 * Reproduced here against two REAL spawned server.js processes sharing
 * the same on-disk data.sqlite across a restart -- not just reading the
 * schema-creation source text -- the same way the keyword-entity test
 * above proves end-to-end behavior, not just that the code looks right.
 */
test("generated server.js migrates a field added to ENTITIES after the first run into the real, already-existing SQLite table, exactly as its own README promises", async () => {
  const customerV1: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [{ name: "name", label: "Name", type: "text", required: true }],
  };
  const customerV2: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [
      { name: "name", label: "Name", type: "text", required: true },
      { name: "email", label: "Email", type: "text", required: false },
    ],
  };
  const projectV1: Project = { ...project, spec: { ...project.spec, entities: [customerV1] } };
  const projectV2: Project = { ...project, spec: { ...project.spec, entities: [customerV2] } };

  const dir = mkdtempSync(path.join(tmpdir(), "codegen-migration-test-"));
  const repoRoot = path.resolve(import.meta.dirname, "../../..");
  symlinkSync(path.join(repoRoot, "node_modules"), path.join(dir, "node_modules"));

  const port = 34000 + Math.floor(Math.random() * 5000);

  async function runServer(project: Project, fn: (port: number) => Promise<void>): Promise<void> {
    const serverJs = generateExportFiles(project).find((f) => f.path === "server.js")!.content;
    writeFileSync(path.join(dir, "server.js"), serverJs);
    const child = spawn(process.execPath, ["--experimental-sqlite", "server.js"], {
      cwd: dir,
      env: { ...process.env, PORT: String(port) },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString();
    });
    try {
      const deadline = Date.now() + 5000;
      let lastErr: unknown;
      while (Date.now() < deadline) {
        if (child.exitCode !== null) {
          throw new Error(`server.js exited early (code ${child.exitCode}):\n${stderr}`);
        }
        try {
          const res = await fetch(`http://localhost:${port}/api/Customer`);
          assert.equal(res.status, 200);
          await fn(port);
          return;
        } catch (err) {
          lastErr = err;
          await new Promise((r) => setTimeout(r, 100));
        }
      }
      throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
    } finally {
      // Waits for the real process exit (not just calling kill() and moving
      // on) -- the next run reopens the exact same data.sqlite file, which
      // needs this process to have actually released its own handle on it
      // first.
      await new Promise<void>((resolve) => {
        child.once("exit", () => resolve());
        child.kill();
      });
    }
  }

  try {
    await runServer(projectV1, async (port) => {
      const createRes = await fetch(`http://localhost:${port}/api/Customer`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ name: "Dana" }),
      });
      assert.equal(createRes.status, 201, "the first run's own write must succeed before the table ever has an 'email' column");
    });

    await runServer(projectV2, async (port) => {
      // The pre-existing row must have survived the restart, with the new
      // column simply unset -- confirms the ALTER TABLE really did run
      // against the SAME table CREATE TABLE IF NOT EXISTS silently skipped
      // re-creating, not a fresh one.
      const listRes = await fetch(`http://localhost:${port}/api/Customer`);
      const { records } = (await listRes.json()) as { records: { name: string; email: string | null }[] };
      assert.equal(records.length, 1, "Dana's own record from the first run must still be there");
      assert.equal(records[0]!.name, "Dana");
      assert.equal(records[0]!.email, null, "the new column must exist (not throw) and simply be unset for a pre-existing row");

      const createRes = await fetch(`http://localhost:${port}/api/Customer`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ name: "Yossi", email: "yossi@example.com" }),
      });
      assert.equal(
        createRes.status,
        201,
        "writing the newly-added field after a restart must succeed via a real migrated column, not fail with a raw 'table has no column' SQLite error",
      );
      const created = (await createRes.json()) as { record: { email: string } };
      assert.equal(created.record.email, "yossi@example.com");
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 1092: the ADD COLUMN migration loop round 802 just confirmed above
 * uses existingColumns.has(field.name) -- an exact, case-sensitive Set
 * lookup. PRAGMA table_info reports a column under whatever casing it was
 * ORIGINALLY created with, and a field renamed only by letter case in the
 * live preview (e.g. "email" -> "Email", a legitimate no-op everywhere
 * else in this codebase -- see migrate.ts's own round-617/618 fix for the
 * identical scenario in the live backend) still resolves to that same
 * physical column once re-exported. Without a case-insensitive fallback,
 * this fell through to ALTER TABLE ADD COLUMN "Email" -- and SQLite's own
 * duplicate-column check IS case-insensitive, so it threw an uncaught
 * "duplicate column name" exception that crashed the WHOLE exported
 * server process on startup (not just one failed request), reproduced
 * here against two real spawned server.js processes sharing the same
 * on-disk data.sqlite across a restart, the same standard as the test
 * immediately above.
 */
test("generated server.js survives a restart after a field is renamed only by letter case, instead of crashing on startup with SQLite's own duplicate-column error", async () => {
  const customerV1: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [{ name: "email", label: "Email", type: "text", required: false }],
  };
  const customerV2: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [{ name: "Email", label: "Email", type: "text", required: false }],
  };
  const projectV1: Project = { ...project, spec: { ...project.spec, entities: [customerV1] } };
  const projectV2: Project = { ...project, spec: { ...project.spec, entities: [customerV2] } };

  const dir = mkdtempSync(path.join(tmpdir(), "codegen-caserename-test-"));
  const repoRoot = path.resolve(import.meta.dirname, "../../..");
  symlinkSync(path.join(repoRoot, "node_modules"), path.join(dir, "node_modules"));

  const port = 34000 + Math.floor(Math.random() * 5000);

  async function runServer(project: Project, fn: (port: number) => Promise<void>): Promise<void> {
    const serverJs = generateExportFiles(project).find((f) => f.path === "server.js")!.content;
    writeFileSync(path.join(dir, "server.js"), serverJs);
    const child = spawn(process.execPath, ["--experimental-sqlite", "server.js"], {
      cwd: dir,
      env: { ...process.env, PORT: String(port) },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString();
    });
    try {
      const deadline = Date.now() + 5000;
      let lastErr: unknown;
      while (Date.now() < deadline) {
        if (child.exitCode !== null) {
          throw new Error(`server.js exited early (code ${child.exitCode}):\n${stderr}`);
        }
        try {
          const res = await fetch(`http://localhost:${port}/api/Customer`);
          assert.equal(res.status, 200);
          await fn(port);
          return;
        } catch (err) {
          lastErr = err;
          await new Promise((r) => setTimeout(r, 100));
        }
      }
      throw lastErr instanceof Error ? lastErr : new Error(String(lastErr));
    } finally {
      await new Promise<void>((resolve) => {
        child.once("exit", () => resolve());
        child.kill();
      });
    }
  }

  try {
    await runServer(projectV1, async (port) => {
      const createRes = await fetch(`http://localhost:${port}/api/Customer`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ email: "dana@example.com" }),
      });
      assert.equal(createRes.status, 201, "the first run's own write must succeed before the rename");
    });

    await runServer(projectV2, async (port) => {
      const listRes = await fetch(`http://localhost:${port}/api/Customer`);
      const { records } = (await listRes.json()) as { records: { Email: string }[] };
      assert.equal(records.length, 1, "the pre-existing row must have survived the restart after a case-only rename");
      assert.equal(records[0]!.Email, "dana@example.com", "the renamed field must resolve to the same physical column, not a fresh null one");

      const createRes = await fetch(`http://localhost:${port}/api/Customer`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ Email: "yossi@example.com" }),
      });
      assert.equal(createRes.status, 201, "writing via the renamed field's new casing must succeed after the restart");
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

// Regression test: the exported standalone app's own coerce() function
// (a separate copy of packages/db/src/repository.ts's coerceValue, since
// this app has no dependency on Forge AI at runtime) validated every
// structured field type except "date", the same gap round 62 found and
