/**
 * Round 686: the same orderedFields convention rounds 615/621/670/678/684
 * already enforce across EntityPanel.tsx's whole-record render paths (and
 * their codegen.ts ports) never reached this module's own exported-app
 * copy either -- confirmed by reading codegen.ts directly: its own
 * generated buildCalendarIcs's descriptionFields still read entity.fields,
 * not the generated handleExportIcs's own already-in-scope orderedFields.
 * Uses the same real-generated-code extraction harness as the two tests
 * above, not a reimplementation.
 */
test("the exported EntityView's real generated buildCalendarIcs lists DESCRIPTION fields in the given orderedFields order, defaulting to entity.fields when none is passed", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const pickDisplaySrc = entityViewJsx.match(/export function pickDisplayField\(entity\) \{[\s\S]*?\n\}\n/)?.[0]?.replace(/^export /, "");
  const labelFieldSrc = entityViewJsx.match(/function calendarLabelField\(entity, dateField\) \{[\s\S]*?\n\}\n/)?.[0];
  const pad2Src = entityViewJsx.match(/function icsPad2\(n\) \{[\s\S]*?\n\}\n/)?.[0];
  const dateSrc = entityViewJsx.match(/function formatIcsDate\(date\) \{[\s\S]*?\n\}\n/)?.[0];
  const tsSrc = entityViewJsx.match(/function formatIcsTimestamp\(date\) \{[\s\S]*?\n\}\n/)?.[0];
  const escSrc = entityViewJsx.match(/function icsEscapeText\(value\) \{[\s\S]*?\n\}\n/)?.[0];
  const utf8LenSrc = entityViewJsx.match(/function utf8ByteLength\(s\) \{[\s\S]*?\n\}\n/)?.[0];
  const foldSrc = entityViewJsx.match(/function foldIcsLine\(line\) \{[\s\S]*?\n\}\n/)?.[0];
  const buildSrc = entityViewJsx.match(
    /function buildCalendarIcs\(entity, dateField, labelField, records, relatedRecords, now, endField, orderedFields = entity\.fields\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(
    pickDisplaySrc && labelFieldSrc && pad2Src && dateSrc && tsSrc && escSrc && utf8LenSrc && foldSrc && buildSrc,
    "expected to find every ICS helper function in the real generated output",
  );

  const relationStub = "function relationDisplayLabel() { return ''; }\n";
  const buildCalendarIcs = new Function(
    `${pickDisplaySrc}\n${labelFieldSrc}\n${pad2Src}\n${dateSrc}\n${tsSrc}\n${escSrc}\n${utf8LenSrc}\n${foldSrc}\n${relationStub}\n${buildSrc}\nreturn buildCalendarIcs;`,
  )() as (
    entity: unknown,
    dateField: unknown,
    labelField: unknown,
    records: unknown[],
    relatedRecords: unknown,
    now: Date,
    endField: unknown,
    orderedFields?: unknown[],
  ) => string;

  const entity = {
    name: "Order",
    label: "Orders",
    fields: [
      { name: "customerName", label: "Customer", type: "text" },
      { name: "date", label: "Date", type: "date" },
      { name: "priority", label: "Priority", type: "text" },
      { name: "notes", label: "Notes", type: "text" },
    ],
  };
  const dateField = entity.fields[1];
  const labelField = entity.fields[0];
  const records = [{ id: 1, customerName: "Dana", date: "2026-03-15", priority: "High", notes: "VIP" }];

  const unordered = buildCalendarIcs(entity, dateField, labelField, records, {}, new Date("2026-01-01T00:00:00Z"), null);
  const unorderedDesc = unordered.match(/DESCRIPTION:.*/)![0];
  assert.ok(
    unorderedDesc.indexOf("Priority") < unorderedDesc.indexOf("Notes"),
    "with no orderedFields argument, DESCRIPTION must follow entity.fields's own declared order (priority before notes)",
  );

  const reordered = [entity.fields[3], entity.fields[1], entity.fields[0], entity.fields[2]]; // notes, date, customerName, priority
  const ics = buildCalendarIcs(entity, dateField, labelField, records, {}, new Date("2026-01-01T00:00:00Z"), null, reordered);
  const desc = ics.match(/DESCRIPTION:.*/)![0];
  assert.ok(desc.indexOf("Notes") < desc.indexOf("Priority"), `DESCRIPTION must list the reordered fields (notes before priority), got: ${desc}`);
});

// Regression test for round 551's finding: PRODID's own content
// (entity.label) was pushed raw in the exported app's generated
// buildCalendarIcs too, unlike UID/SUMMARY/DESCRIPTION which already go
// through foldIcsLine -- reuses the exact same real-generated-code
// extraction harness as the test immediately above, just with a long
// entity label to force the raw line past 75 UTF-8 octets.
test("the exported EntityView's real generated buildCalendarIcs folds a long PRODID line the same way it folds DESCRIPTION", () => {
  const withDate: Project = {
    ...project,
    spec: {
      ...project.spec,
      entities: [
        ...project.spec.entities,
        {
          name: "Appointment",
          label: "לקוח ".repeat(30),
          fields: [
            { name: "customerName", label: "שם לקוח", type: "text", required: true },
            { name: "date", label: "תאריך", type: "date", required: true },
          ],
        },
      ],
    },
  };
  const entityViewJsx = generateExportFiles(withDate).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const pickDisplaySrc = entityViewJsx.match(/export function pickDisplayField\(entity\) \{[\s\S]*?\n\}\n/)?.[0]?.replace(/^export /, "");
  const labelFieldSrc = entityViewJsx.match(/function calendarLabelField\(entity, dateField\) \{[\s\S]*?\n\}\n/)?.[0];
  const pad2Src = entityViewJsx.match(/function icsPad2\(n\) \{[\s\S]*?\n\}\n/)?.[0];
  const dateSrc = entityViewJsx.match(/function formatIcsDate\(date\) \{[\s\S]*?\n\}\n/)?.[0];
  const tsSrc = entityViewJsx.match(/function formatIcsTimestamp\(date\) \{[\s\S]*?\n\}\n/)?.[0];
  const escSrc = entityViewJsx.match(/function icsEscapeText\(value\) \{[\s\S]*?\n\}\n/)?.[0];
  const utf8LenSrc = entityViewJsx.match(/function utf8ByteLength\(s\) \{[\s\S]*?\n\}\n/)?.[0];
  const foldSrc = entityViewJsx.match(/function foldIcsLine\(line\) \{[\s\S]*?\n\}\n/)?.[0];
  const buildSrc = entityViewJsx.match(
    /function buildCalendarIcs\(entity, dateField, labelField, records, relatedRecords, now, endField, orderedFields = entity\.fields\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(
    pickDisplaySrc && labelFieldSrc && pad2Src && dateSrc && tsSrc && escSrc && utf8LenSrc && foldSrc && buildSrc,
    "expected to find every ICS helper function in the real generated output",
  );

  const relationStub = "function relationDisplayLabel() { return ''; }\n";
  const buildCalendarIcs = new Function(
    `${pickDisplaySrc}\n${labelFieldSrc}\n${pad2Src}\n${dateSrc}\n${tsSrc}\n${escSrc}\n${utf8LenSrc}\n${foldSrc}\n${relationStub}\n${buildSrc}\nreturn buildCalendarIcs;`,
  )() as (entity: unknown, dateField: unknown, labelField: unknown, records: unknown[], relatedRecords: unknown, now: Date) => string;

  const entity = {
    name: "Appointment",
    label: "לקוח ".repeat(30),
    fields: [
      { name: "customerName", label: "שם לקוח", type: "text" },
      { name: "date", label: "תאריך", type: "date" },
    ],
  };
  assert.ok(
    new TextEncoder().encode(`PRODID:-//Forge AI//${entity.label}//EN`).length > 75,
    "sanity check: this label makes the raw PRODID line exceed 75 UTF-8 octets",
  );
  const dateField = entity.fields[1];
  const labelField = entity.fields[0];

  const ics = buildCalendarIcs(entity, dateField, labelField, [], {}, new Date("2026-01-01T00:00:00Z"));
  const lines = ics.split("\r\n");
  const prodidLineIndex = lines.findIndex((l) => l.startsWith("PRODID:"));
  assert.ok(prodidLineIndex >= 0);

  const prodidPhysicalLines = [lines[prodidLineIndex]];
  let i = prodidLineIndex;
  while (lines[i + 1]?.startsWith(" ")) {
    i += 1;
    prodidPhysicalLines.push(lines[i]);
  }
  assert.ok(prodidPhysicalLines.length > 1, "a PRODID line this long in real bytes must actually be folded into more than one physical line");
  for (const line of prodidPhysicalLines) {
    const byteLength = new TextEncoder().encode(line).length;
    assert.ok(byteLength <= 75, `every folded PRODID physical line must be <=75 UTF-8 octets, was ${byteLength}: ${JSON.stringify(line)}`);
  }
});

// Regression test for round 601's finding: the exported app's own
// buildCalendarIcs (ported from calendarIcs.ts) pushed entity.name raw
// into the UID line with no icsEscapeText call, unlike PRODID/SUMMARY/
// DESCRIPTION in the same function -- an entity name containing a
// semicolon, comma, or backslash reached the UID content line unescaped,
// breaking RFC 5545's content-line structure in the one output (a
// downloaded, standalone exported app's .ics file) real end users
// actually import into real calendar apps. Mirrors calendarIcs.test.ts's
// own UID-escaping test for the un-exported version; reuses the same
// real-generated-code extraction harness as the PRODID-folding test
// immediately above (the project's own entity name stays normal so
// generation doesn't choke on it -- only the entity object buildCalendarIcs
// is actually invoked with carries the unsafe name).
test("the exported EntityView's real generated buildCalendarIcs escapes an entity name containing RFC-5545-significant characters in UID, same as PRODID/SUMMARY/DESCRIPTION", () => {
  const withDate: Project = {
    ...project,
    spec: {
      ...project.spec,
      entities: [
        ...project.spec.entities,
        {
          name: "Appointment",
          label: "לקוח",
          fields: [
            { name: "customerName", label: "שם לקוח", type: "text", required: true },
            { name: "date", label: "תאריך", type: "date", required: true },
          ],
        },
      ],
    },
  };
  const entityViewJsx = generateExportFiles(withDate).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const pickDisplaySrc = entityViewJsx.match(/export function pickDisplayField\(entity\) \{[\s\S]*?\n\}\n/)?.[0]?.replace(/^export /, "");
  const labelFieldSrc = entityViewJsx.match(/function calendarLabelField\(entity, dateField\) \{[\s\S]*?\n\}\n/)?.[0];
  const pad2Src = entityViewJsx.match(/function icsPad2\(n\) \{[\s\S]*?\n\}\n/)?.[0];
  const dateSrc = entityViewJsx.match(/function formatIcsDate\(date\) \{[\s\S]*?\n\}\n/)?.[0];
  const tsSrc = entityViewJsx.match(/function formatIcsTimestamp\(date\) \{[\s\S]*?\n\}\n/)?.[0];
  const escSrc = entityViewJsx.match(/function icsEscapeText\(value\) \{[\s\S]*?\n\}\n/)?.[0];
  const utf8LenSrc = entityViewJsx.match(/function utf8ByteLength\(s\) \{[\s\S]*?\n\}\n/)?.[0];
  const foldSrc = entityViewJsx.match(/function foldIcsLine\(line\) \{[\s\S]*?\n\}\n/)?.[0];
  const buildSrc = entityViewJsx.match(
    /function buildCalendarIcs\(entity, dateField, labelField, records, relatedRecords, now, endField, orderedFields = entity\.fields\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(
    pickDisplaySrc && labelFieldSrc && pad2Src && dateSrc && tsSrc && escSrc && utf8LenSrc && foldSrc && buildSrc,
    "expected to find every ICS helper function in the real generated output",
  );

  const relationStub = "function relationDisplayLabel() { return ''; }\n";
  const buildCalendarIcs = new Function(
    `${pickDisplaySrc}\n${labelFieldSrc}\n${pad2Src}\n${dateSrc}\n${tsSrc}\n${escSrc}\n${utf8LenSrc}\n${foldSrc}\n${relationStub}\n${buildSrc}\nreturn buildCalendarIcs;`,
  )() as (entity: unknown, dateField: unknown, labelField: unknown, records: unknown[], relatedRecords: unknown, now: Date) => string;

  const entity = {
    name: "Weird;Name,With\\Chars",
    label: "לקוח",
    fields: [
      { name: "customerName", label: "שם לקוח", type: "text" },
      { name: "date", label: "תאריך", type: "date" },
    ],
  };
  const dateField = entity.fields[1];
  const labelField = entity.fields[0];
  const records = [{ id: 3, customerName: "Dana Levi", date: "2026-03-15" }];

  const ics = buildCalendarIcs(entity, dateField, labelField, records, {}, new Date("2026-01-01T00:00:00Z"));
  assert.match(ics, /UID:Weird\\;Name\\,With\\\\Chars-3@proj1\.forge-ai/);
  assert.doesNotMatch(ics, /UID:Weird;Name,With\\Chars-3@proj1\.forge-ai/, "the raw unescaped name must never reach the UID line");
});

