  const ics = buildCalendarIcs(entity, dateField, labelField, records, {}, new Date("2026-01-01T00:00:00Z"));

  assert.match(ics, /מאושר: TRUE/, "a true boolean field must render uppercase TRUE, not JS's own lowercase \"true\"");
