test("the exported app includes a real cross-entity global search, ported from the Forge AI live preview", () => {
  const files = generateExportFiles(project);
  const globalSearchJsx = files.find((f) => f.path === "web/src/components/GlobalSearch.jsx")!.content;
  // Reuses EntityView's own matchesSearch/recordDisplayLabel rather than
  // re-implementing the matching rule a second time. markDialogOpen/
  // markDialogClosed/DIALOG_FOCUSABLE_SELECTOR/hideDialogBackgroundFromAssistiveTech
  // were generalized in round 650 (no longer search-specific names) once
  // ShortcutsPanel.jsx became a second dialog sharing the same guard.
  // entityLabelOccurrences/entityDisplayLabel were added later for entity-
  // label disambiguation in result group headers, and Highlighted in round
  // 963 (see its own test below) -- this regex had drifted stale after both
  // additions, silently never matching anything since (confirmed via a
  // scoped git-stash check against the pre-round-963 file), without
  // surfacing as a visible failure: codegen.test.ts's own well-documented
  // whole-file exit flake marks the entire file "not ok" at the TAP level
  // regardless of which individual subtests pass, so a single broken
  // assertion buried among hundreds of real passes went unnoticed by the
  // file-level pass/fail counts this routine's own rounds have been
  // tracking. Corrected here since this round's own fix touches this exact
  // import list anyway.
  assert.match(
    globalSearchJsx,
    /import \{\s*matchesSearch,\s*recordDisplayLabel,\s*markDialogOpen,\s*markDialogClosed,\s*DIALOG_FOCUSABLE_SELECTOR,\s*hideDialogBackgroundFromAssistiveTech,\s*scrollIntoViewRespectingMotion,\s*entityLabelOccurrences,\s*entityDisplayLabel,\s*Highlighted,\s*\} from ".\/EntityView\.jsx";/,
  );
  assert.match(globalSearchJsx, /export function GlobalSearch/);
  assert.match(globalSearchJsx, /global-search-group-selected/);
  assert.match(globalSearchJsx, /ArrowDown/);
  assert.match(globalSearchJsx, /ArrowUp/);

  // EntityView.jsx must actually export what GlobalSearch.jsx imports.
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;
  assert.match(entityViewJsx, /export function matchesSearch/);
  assert.match(entityViewJsx, /export function recordDisplayLabel/);

  // App.jsx wires it up: Ctrl/Cmd+K opens it, each entity import also pulls
  // in that entity's own field list (needed to search its records), and a
  // visible shortcut hint makes the affordance discoverable.
  const appJsx = files.find((f) => f.path === "web/src/App.jsx")!.content;
  assert.match(appJsx, /import \{ GlobalSearch \} from ".\/components\/GlobalSearch\.jsx"/);
  assert.match(appJsx, /entity as CustomerEntity/);
  assert.match(appJsx, /fields: CustomerEntity\.fields/);
  assert.match(appJsx, /ctrlKey \|\| e\.metaKey/);
  // Regression test for round 665: the badge text itself must list BOTH
  // real shortcuts the handler above actually opens search with (Ctrl/Cmd+K
  // and "/") -- a bare /shortcut-hint/ match (this test's own pre-fix
  // assertion) passes regardless of the span's content, so it never caught
  // the badge silently falling behind when "/" was ported into this same
  // handler (round 629) without updating the text next to the button that
  // advertises it, the same "static UI text vs. real behavior" gap round
  // 664 found in ShortcutsPanel.jsx.
  assert.match(appJsx, /<span className="shortcut-hint">Ctrl\+K · \/<\/span>/);
});

