/**
 * New in this round: the exported standalone app's entity table columns
 * were a fixed auto-layout width, unlike the live Forge AI preview (round
 * 185's own drag-to-resize columns, persisted per entity via
 * localStorage). Ports the identical clamped drag-math. Executes the real
 * generated function (extracted from real codegen output, not
 * reimplemented), mirroring apps/web/src/columnWidths.test.ts's own
 * computeResizedWidth coverage -- minus the RTL direction parameter, since
 * the exported app has no lang/dir switching at all (round 200's own note).
 */
test("the exported EntityView's computeResizedWidth clamps a dragged column between MIN_COLUMN_WIDTH and MAX_COLUMN_WIDTH", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;
  const fnSrc = entityViewJsx
    .match(/const MIN_COLUMN_WIDTH[\s\S]*?export function computeResizedWidth\(startWidth, deltaX\) \{[\s\S]*?\n\}\n/)?.[0]
    ?.replace("export ", "");
  assert.ok(fnSrc, "expected to find computeResizedWidth (with its MIN/MAX constants) in generated output");

  const computeResizedWidth = new Function(`${fnSrc}\nreturn computeResizedWidth;`)() as (startWidth: number, deltaX: number) => number;

  assert.equal(computeResizedWidth(150, 40), 190, "an ordinary drag must widen by exactly the mouse delta");
  assert.equal(computeResizedWidth(150, -40), 110, "dragging the other way must narrow by exactly the mouse delta");
  assert.equal(computeResizedWidth(150, -1000), 60, "must clamp to MIN_COLUMN_WIDTH rather than going arbitrarily narrow");
  assert.equal(computeResizedWidth(150, 1000), 480, "must clamp to MAX_COLUMN_WIDTH rather than going arbitrarily wide");
});

test("the exported EntityView's table headers are drag-resizable, persisting per entity via a real localStorage round trip", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  // Pre-existing staleness found while verifying round 1030: round 986
  // rewrote this into a multi-line initializer (to remap a stale
  // field-case entry on read), so the plain one-liner this regex expected
  // has never matched since -- never caught before because every full
  // suite run hits this file's own known mid-run SIGKILL well before
  // reaching this test (see docs/roadmap.md's standing note on
  // codegen.test.ts). Checks the same essential fact (the initializer
  // still sources its value from getColumnWidths(entity.name)) against
  // the real current shape instead.
  assert.match(entityViewJsx, /const \[columnWidths, setColumnWidths\] = useState\(\(\) => \{\s*const loaded = getColumnWidths\(entity\.name\);/);
  assert.match(entityViewJsx, /const \[resizingField, setResizingField\] = useState\(null\);/);
  // The drag must only ever attach real mousemove/mouseup listeners while a
  // drag is actually in progress, and must persist to localStorage only on
  // mouseup (via setColumnWidth) -- not on every mousemove.
  assert.match(
    entityViewJsx,
    /useEffect\(\(\) => \{\s*if \(!resizingField\) return;\s*function handleMove\(e\) \{\s*const width = computeResizedWidth\(resizingField\.startWidth, e\.clientX - resizingField\.startX\);\s*setColumnWidths\(\(prev\) => \(\{ \.\.\.prev, \[resizingField\.field\]: width \}\)\);\s*\}\s*function handleUp\(\) \{\s*setColumnWidths\(\(prev\) => \{\s*const width = prev\[resizingField\.field\];\s*if \(width != null\) setColumnWidth\(entity\.name, resizingField\.field, width\);\s*return prev;\s*\}\);\s*setResizingField\(null\);\s*\}/,
  );
  assert.match(entityViewJsx, /onMouseDown=\{\(e\) => startResize\(e, f\.name\)\}/);
  // The reset-on-entity-switch effect must reload the new entity's own
  // widths -- the exact class of bug round 198 shipped and Playwright
  // caught (a stale reference to state that had been renamed/removed).
  assert.match(entityViewJsx, /setColumnWidths\(getColumnWidths\(entity\.name\)\);\s*setColumnOrderState\(getColumnOrder\(entity\.name\)\);\s*refresh\(\);/);

  const stylesCss = files.find((f) => f.path === "web/src/styles.css")!.content;
  assert.match(stylesCss, /\.column-resize-handle/);
  assert.match(stylesCss, /\.entity-table-resized/);

  // Executes the real generated getColumnWidths/setColumnWidth against a
  // fake localStorage, the same "run the real generated code" standard this
  // file's other persistence-backed tests use (see getHiddenColumns/
  // toggleColumnVisibility below).
  // Round 1030: also captures migrateEntityStoreKeyCase -- see the
  // identical note on the hiddenColumns test below for why.
  const storeSrc = entityViewJsx.match(
    /function migrateEntityStoreKeyCase\(store, entityName, writeStore\) \{[\s\S]*?\nfunction setColumnWidth\(entityName, fieldName, width\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(storeSrc, "expected to find the column-widths store functions in generated output");

  const fakeStorage: Record<string, string> = {};
  const { getColumnWidths, setColumnWidth } = new Function(
    "localStorage",
    `${storeSrc}\nreturn { getColumnWidths, setColumnWidth };`,
  )({
    getItem: (k: string) => fakeStorage[k] ?? null,
    setItem: (k: string, v: string) => {
      fakeStorage[k] = v;
    },
  }) as { getColumnWidths: (e: string) => Record<string, number>; setColumnWidth: (e: string, f: string, w: number) => Record<string, number> };

  assert.deepEqual(getColumnWidths("Order"), {}, "an entity with no resized column must start with an empty width map");
  const updated = setColumnWidth("Order", "customerName", 220);
  assert.deepEqual(updated, { customerName: 220 });
  assert.deepEqual(getColumnWidths("Order"), { customerName: 220 }, "must round-trip through the real localStorage-backed store");
  assert.deepEqual(getColumnWidths("Courier"), {}, "a different entity's own widths must not leak across entities");
});

/**
 * New in this round: table columns in the exported standalone app could
 * only be resized (round 201) or hidden (round 198's own "Columns" menu
 * port) -- never actually REORDERED, unlike the live Forge AI preview
 * (round 203). Ports the identical draggable/onDragStart/onDragOver/
 * onDragLeave/onDrop contract EntityPanel.tsx's own column-header drag
 * already uses, reusing applyColumnOrder/reorderColumns verbatim rather
 * than reimplementing the reorder math (they're already generic over any
 * `{name}[]`, and a field object here has the same shape a live-preview
 * field does).
 */
test("the exported EntityView's table columns are drag-and-drop reorderable, persisting per entity via a real localStorage round trip", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  assert.match(entityViewJsx, /const \[columnOrder, setColumnOrderState\] = useState\(\(\) => getColumnOrder\(entity\.name\)\);/);
  assert.match(entityViewJsx, /const \[draggedField, setDraggedField\] = useState\(null\);/);
  assert.match(
    entityViewJsx,
    /const orderedFields = useMemo\(\(\) => applyColumnOrder\(entity\.fields, columnOrder\), \[entity\.fields, columnOrder\]\);/,
  );
  assert.match(
    entityViewJsx,
    /function handleReorderColumn\(targetName\) \{\s*setDragOverField\(null\);\s*if \(!draggedField \|\| draggedField === targetName\) return;\s*const fullOrder = orderedFields\.map\(\(f\) => f\.name\);\s*setColumnOrderState\(setColumnOrder\(entity\.name, reorderColumns\(fullOrder, draggedField, targetName\)\)\);\s*setDraggedField\(null\);\s*\}/,
  );
  assert.match(entityViewJsx, /onDragStart=\{\(\) => setDraggedField\(f\.name\)\}/);
  assert.match(entityViewJsx, /onDrop=\{\(e\) => \{\s*e\.preventDefault\(\);\s*handleReorderColumn\(f\.name\);\s*\}\}/);
  // The reset-on-entity-switch effect must reload the new entity's own
  // persisted order -- the exact class of bug round 198 shipped and
  // Playwright caught (a stale reference to state that had been
  // renamed/removed), re-verified for every new piece of per-entity state.
  assert.match(entityViewJsx, /setColumnOrderState\(getColumnOrder\(entity\.name\)\);\s*refresh\(\);/);

  const stylesCss = files.find((f) => f.path === "web/src/styles.css")!.content;
  assert.match(stylesCss, /\.resizable-col-drag-over/);

  // Executes the real generated applyColumnOrder/reorderColumns and the
  // real generated getColumnOrder/setColumnOrder against a fake
  // localStorage -- the same "run the real generated code" standard this
  // file's other persistence-backed tests use.
  const pureFnSrc = entityViewJsx.match(
    /function applyColumnOrder\(fields, order\) \{[\s\S]*?\nfunction reorderColumns\(order, sourceName, targetName\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(pureFnSrc, "expected to find applyColumnOrder/reorderColumns in generated output");
  const { applyColumnOrder, reorderColumns } = new Function(`${pureFnSrc}\nreturn { applyColumnOrder, reorderColumns };`)() as {
    applyColumnOrder: (fields: { name: string }[], order: string[]) => { name: string }[];
    reorderColumns: (order: string[], source: string, target: string) => string[];
  };
  assert.deepEqual(
    applyColumnOrder([{ name: "name" }, { name: "status" }], ["status", "name"]).map((f) => f.name),
    ["status", "name"],
  );
  assert.deepEqual(reorderColumns(["name", "status"], "status", "name"), ["status", "name"]);
  const unchanged = ["name", "status"];
  assert.equal(reorderColumns(unchanged, "status", "status"), unchanged, "dropping a column back onto itself must be a real no-op");

  // Round 1030: also captures migrateEntityStoreKeyCase, prepended
  // separately rather than widening storeSrc's own span to reach back to
  // it -- that span crosses the exported `computeResizedWidth` between
  // the column-widths and column-order sections, and `export` is not
  // valid inside a plain Function body ("Unexpected token 'export'").
  const migrateHelperSrc = entityViewJsx.match(/function migrateEntityStoreKeyCase\(store, entityName, writeStore\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(migrateHelperSrc, "expected to find migrateEntityStoreKeyCase in generated output");
  const storeSrc = entityViewJsx.match(/const COLUMN_ORDER_STORAGE_KEY[\s\S]*?\nfunction setColumnOrder\(entityName, order\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(storeSrc, "expected to find the column-order store functions in generated output");
  const fakeStorage: Record<string, string> = {};
  const { getColumnOrder, setColumnOrder } = new Function(
    "localStorage",
    `${migrateHelperSrc}\n${storeSrc}\nreturn { getColumnOrder, setColumnOrder };`,
  )({
    getItem: (k: string) => fakeStorage[k] ?? null,
    setItem: (k: string, v: string) => {
      fakeStorage[k] = v;
    },
  }) as { getColumnOrder: (e: string) => string[]; setColumnOrder: (e: string, order: string[]) => string[] };

  assert.deepEqual(getColumnOrder("Order"), [], "an entity with no reordered columns must start with an empty order");
  const updated = setColumnOrder("Order", ["status", "customerName"]);
  assert.deepEqual(updated, ["status", "customerName"]);
  assert.deepEqual(getColumnOrder("Order"), ["status", "customerName"], "must round-trip through the real localStorage-backed store");
  assert.deepEqual(getColumnOrder("Courier"), [], "a different entity's own order must not leak across entities");
});

/**
 * New in this round: the exported standalone app's Kanban board could only
 * move a card between columns via its own <select>, unlike the live Forge
 * AI preview (round 186's own native HTML5 drag-and-drop). Ports the
 * identical drag mechanics -- draggable cards, drop targets that highlight
 * while dragged over, and a real no-op guard for dropping a card back onto
 * its own column.
 */
test("the exported EntityView's Kanban board cards are drag-and-drop-able onto another column, reusing the same handleMove the dropdown already calls", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  assert.match(entityViewJsx, /const \[dragOverColumn, setDragOverColumn\] = useState\(null\);/);
  // BoardCard itself must be a real native drag source, not just visually styled.
  assert.match(
    entityViewJsx,
    /<div className=\{hasMoveError \? "board-card board-card-move-error" : "board-card"\} draggable onDragStart=\{\(e\) => e\.dataTransfer\.setData\("text\/plain", String\(record\.id\)\)\}>/,
  );
  // handleCardDrop must guard against a real no-op (dropping a card back onto its own column) before ever calling handleMove.
  const dropSrc = entityViewJsx.match(/function handleCardDrop\(e, fieldName, value\) \{[\s\S]*?\n {2}\}\n/)?.[0];
  assert.ok(dropSrc, "expected to find handleCardDrop in generated output");
  assert.match(dropSrc!, /const record = records\.find\(\(r\) => r\.id === id\);/);
  // Round 656: a column accepts any drag, not just a real card -- without
  // this guard, a drag with no real record id (an entity tab, which never
  // calls setData, or a file from the desktop) fell through to a real
  // PATCH for a nonexistent record.
  assert.match(dropSrc!, /if \(!record\) return;/);
  assert.match(dropSrc!, /if \(String\(record\[fieldName\] \?\? ""\) === value\) return;/);
  assert.match(dropSrc!, /void handleMove\(id, fieldName, value\);/);
  // The column itself must be a real drop target, highlighted only while actually dragged over -- except
  // the synthetic "(other)" column (see the "(other)" bucket test below), which must guard out of both.
  assert.match(
    entityViewJsx,
    /onDragOver=\{\(e\) => \{\s*if \(column\.isOther\) return;\s*e\.preventDefault\(\);\s*setDragOverColumn\(column\.value\);\s*\}\}/,
  );
  assert.match(entityViewJsx, /onDragLeave=\{\(\) => setDragOverColumn\(\(prev\) => \(prev === column\.value \? null : prev\)\)\}/);
  assert.match(
    entityViewJsx,
    /onDrop=\{\(e\) => \{\s*if \(column\.isOther\) return;\s*handleCardDrop\(e, boardField\.name, column\.value\);\s*\}\}/,
  );
  assert.match(
    entityViewJsx,
    /className=\{\s*dragOverColumn === column\.value\s*\? "board-column board-column-drag-over"\s*: column\.isOther\s*\? "board-column board-column-other"\s*: "board-column"\s*\}/,
  );

  const stylesCss = files.find((f) => f.path === "web/src/styles.css")!.content;
  assert.match(stylesCss, /\.board-column-drag-over/);
  assert.match(stylesCss, /\.board-column-other/);
});

/**
 * Regression test for round 656: a board column's own onDragOver accepts
 * ANY drag, not just one of its own cards -- so an entity tab (its own
 * onDragStart never calls setData, leaving its text/plain payload "") or a
 * file dragged in from the desktop both land in handleCardDrop too.
 * Number("") is 0, not NaN, so the old Number.isNaN guard alone let it
 * straight through to a `records.find` that returns undefined, and the
 * old same-column check (`record && ...`) short-circuited false and fell
 * through to a real PATCH for a record id that was never actually
 * dragged. Confirms a drop with an empty text/plain payload is a true
 * no-op in the exported app too: no PATCH fires and the real record's
 * status is untouched.
 */
test("the exported EntityView's board column drop with no real record id is a silent no-op, not a PATCH to a nonexistent record", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const store = [{ id: 1, name: "Acme Corp", status: "New" }];
  const originalFetch = globalThis.fetch;
  let patchCount = 0;
  globalThis.fetch = (async (input: string, init?: RequestInit): Promise<Response> => {
    const method = init?.method ?? "GET";
    if (method === "GET" && input === "/api/Customer") {
      return new Response(JSON.stringify({ records: store }), { status: 200, headers: { "content-type": "application/json" } });
    }
    if (method === "PATCH") {
      patchCount += 1;
      return new Response(JSON.stringify({ record: store[0] }), { status: 200, headers: { "content-type": "application/json" } });
    }
    throw new Error(`unexpected request ${method} ${input}`);
  }) as typeof fetch;

  try {
    await withRealLocalStorage(async () => {
      const { EntityView } = await import(path.join(dir, "web", "src", "components", "EntityView.jsx"));
      const customerEntity = project.spec.entities.find((e) => e.name === "Customer")!;
      const props = {
        entity: customerEntity,
        highlightRecordId: null,
        onHighlightHandled: () => {},
        onJumpToRecord: () => {},
        onRecordCountChange: () => {},
      };

      const { container } = render(React.createElement(EntityView, props));
      let boardToggle: HTMLButtonElement | undefined;
      for (let i = 0; i < 40; i++) {
        boardToggle = Array.from(container.querySelectorAll("button")).find((b) => b.textContent?.includes("Board")) as HTMLButtonElement;
        if (boardToggle) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }
      assert.ok(boardToggle, "expected a Board view-toggle button");
      await act(async () => {
        fireEvent.click(boardToggle!);
      });
      for (let i = 0; i < 40; i++) {
        if (container.querySelectorAll(".board-column").length > 0) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }

      const columns = container.querySelectorAll(".board-column");
      assert.ok(columns.length >= 2, "expected at least 2 board columns (New, Won)");
      // An entity tab's own onDragStart never calls setData -- simulate the
      // exact same empty payload a real such drag (or a file from the
      // desktop) would leave behind.
      const emptyDataTransfer = { getData: () => "" };

      await act(async () => {
        fireEvent.drop(columns[1], { dataTransfer: emptyDataTransfer });
      });
      await act(async () => {
        await new Promise((resolve) => setImmediate(resolve));
      });

      assert.equal(patchCount, 0, "a drop with no real record id must never call the real PATCH endpoint");
      assert.equal(store[0].status, "New", "the only real record's status must be completely untouched");
    });
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

// Executes the real generated isInlineEditableField (extracted from real
// codegen output, not reimplemented), the same "run the real generated
// code" standard this file's other pure-function tests use. Mirrors the
// live preview's own entityFormatting.test.ts coverage for
// isInlineEditableField (round 206).
test("the exported EntityView's isInlineEditableField allows every field type except relation and file", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;
  const fnSrc = entityViewJsx.match(/export function isInlineEditableField\(field\) \{[\s\S]*?\n\}\n/)?.[0]?.replace("export ", "");
  assert.ok(fnSrc, "expected to find isInlineEditableField in generated output");
  const isInlineEditableField = new Function(`${fnSrc}\nreturn isInlineEditableField;`)() as (field: { type: string }) => boolean;

  for (const type of ["text", "longtext", "number", "boolean", "enum", "date"]) {
    assert.equal(isInlineEditableField({ type }), true, `expected ${type} to be inline-editable`);
  }
  assert.equal(isInlineEditableField({ type: "relation" }), false, "a relation field's cell shows a label resolved from a different record, so it must stay excluded");
  // New in this round: a file field's cell showed just the attachment's
  // filename (via parseFileFieldValue), not the raw JSON descriptor an
  // inline editor would need to edit -- without this exclusion,
  // double-clicking it let a user type free text over that raw JSON,
  // corrupting the stored attachment.
  assert.equal(isInlineEditableField({ type: "file" }), false, "a file field's real editing UI needs an upload endpoint this exported app doesn't have, so it must stay excluded");
});

/**
 * New in this round: every scrollIntoView call in the exported app passed
 * behavior: "smooth" unconditionally, regardless of whether the person
 * has their OS/browser set to "prefers-reduced-motion: reduce" -- the
 * exact WCAG 2.3.3 case the live preview's fix (and this exported app's
 * own styles.css, which already disables its .hero3d-cube animation
 * under this same media query) treats as real. Runs the real generated
 * scrollIntoViewRespectingMotion, not a reimplementation.
 */
test("the exported EntityView's scrollIntoViewRespectingMotion substitutes behavior: \"auto\" for \"smooth\" when prefers-reduced-motion is set, and leaves it alone otherwise", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;
  const fnSrc = entityViewJsx.match(/export function scrollIntoViewRespectingMotion\(el, options\) \{[\s\S]*?\n\}\n/)?.[0]?.replace("export ", "");
  assert.ok(fnSrc, "expected to find scrollIntoViewRespectingMotion in generated output");
  const scrollIntoViewRespectingMotion = new Function(`${fnSrc}\nreturn scrollIntoViewRespectingMotion;`)() as (
    el: { scrollIntoView: (options: unknown) => void } | null | undefined,
    options: Record<string, unknown>,
  ) => void;

  const originalWindow = (globalThis as { window?: unknown }).window;
  try {
    (globalThis as { window?: unknown }).window = { matchMedia: () => ({ matches: true }) };
    const reducedCalls: unknown[] = [];
    scrollIntoViewRespectingMotion({ scrollIntoView: (o) => reducedCalls.push(o) }, { behavior: "smooth", block: "center" });
    assert.deepEqual(reducedCalls, [{ behavior: "auto", block: "center" }]);

    (globalThis as { window?: unknown }).window = { matchMedia: () => ({ matches: false }) };
    const normalCalls: unknown[] = [];
    scrollIntoViewRespectingMotion({ scrollIntoView: (o) => normalCalls.push(o) }, { behavior: "smooth", block: "center" });
    assert.deepEqual(normalCalls, [{ behavior: "smooth", block: "center" }]);

    assert.doesNotThrow(() => scrollIntoViewRespectingMotion(null, { behavior: "smooth" }));
    assert.doesNotThrow(() => scrollIntoViewRespectingMotion(undefined, { behavior: "smooth" }));
  } finally {
    (globalThis as { window?: unknown }).window = originalWindow;
  }
});

// Confirms every one of the four real scrollIntoView call sites this
// round touched (two in EntityView.jsx, one in GlobalSearch.jsx, plus
// startCreateNew) actually routes through scrollIntoViewRespectingMotion
// now, rather than calling the DOM method directly -- checked against the
// specific old call patterns each site used (not a blanket "no
// .scrollIntoView(" scan, which would also flag the wrapper's own,
// necessary internal call); the function's own correctness is covered
// end-to-end above. Round 821's own fix added two more EntityView.jsx call
// sites (startCreateForColumn/startCreateForDate, the Board/Calendar
// siblings of startCreateNew that used to skip the scroll entirely) --
// counted below alongside the original four.
test("every scrollIntoView call site in the exported app routes through scrollIntoViewRespectingMotion, not a direct DOM call", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;
  const globalSearchJsx = files.find((f) => f.path === "web/src/components/GlobalSearch.jsx")!.content;

  assert.doesNotMatch(entityViewJsx, /row\?\.scrollIntoView\?\.\(/, "the highlighted-row/focused-row effects must no longer call scrollIntoView directly");
  assert.doesNotMatch(entityViewJsx, /formEl\?\.scrollIntoView\?\.\(/, "startCreateNew must no longer call scrollIntoView directly");
  assert.doesNotMatch(globalSearchJsx, /group\.scrollIntoView\(/, "the arrow-key result-group scroll must no longer call scrollIntoView directly");

  const entityViewCallCount = (entityViewJsx.match(/scrollIntoViewRespectingMotion\(/g) ?? []).length;
  assert.equal(
    entityViewCallCount,
    6,
    "expected exactly 6 occurrences in EntityView.jsx: the function's own definition, the highlighted-row effect, the focused-row effect, startCreateNew, startCreateForColumn, and startCreateForDate",
  );

  assert.match(globalSearchJsx, /scrollIntoViewRespectingMotion,\n\} from "\.\/EntityView\.jsx";/, "GlobalSearch.jsx must import the shared helper from EntityView.jsx rather than duplicating it");
  const globalSearchCallCount = (globalSearchJsx.match(/scrollIntoViewRespectingMotion\(/g) ?? []).length;
  assert.equal(globalSearchCallCount, 1, "expected exactly 1 call site in GlobalSearch.jsx: the arrow-key result-group scroll");
});

/**
 * New in this round: the exported app's own Cell, matchesSearch, and
 * fieldDisplayValue (CSV export) all had zero support for the "file"
 * field type -- every other surface of this same codebase (the live
 * Forge AI preview's entityFormatting.ts, the backup ZIP's CSV export)
 * already parses a file field's stored {url, name, size, mimeType} JSON
 * descriptor and shows just the filename, but this exported app fell
 * through to String(value) everywhere, dumping the raw JSON into the
 * table cell, the CSV export, and (over-/under-)matching it in search.
 * Runs the real generated Cell/matchesSearch/fieldDisplayValue (plus the
 * parseFileFieldValue/isImageMimeType helpers they depend on), not a
 * reimplementation.
 */
test("the exported EntityView's Cell, matchesSearch, and fieldDisplayValue all show a file field's real filename, not its raw JSON descriptor", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const parseFileFieldValueSrc = entityViewJsx.match(/function parseFileFieldValue\(value\) \{[\s\S]*?\n\}\n/)?.[0];
  const isImageMimeTypeSrc = entityViewJsx.match(/function isImageMimeType\(mimeType\) \{[\s\S]*?\n\}\n/)?.[0];
  const matchesSearchSrc = entityViewJsx.match(/export function matchesSearch\([\s\S]*?\n\}\n/)?.[0]?.replace("export ", "");
  const fieldDisplayValueSrc = entityViewJsx.match(/function fieldDisplayValue\(field, value, relatedRecords\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(
    parseFileFieldValueSrc && isImageMimeTypeSrc && matchesSearchSrc && fieldDisplayValueSrc,
    "expected to find parseFileFieldValue/isImageMimeType/matchesSearch/fieldDisplayValue in generated output",
  );

  const fileValue = JSON.stringify({ url: "https://files.example.com/invoice.pdf", name: "invoice.pdf", size: 1024, mimeType: "application/pdf" });

  const { matchesSearch } = new Function(`${parseFileFieldValueSrc}\n${matchesSearchSrc}\nreturn { matchesSearch };`)() as {
    matchesSearch: (record: unknown, fields: unknown[], query: string) => boolean;
  };
  const fields = [{ name: "attachment", type: "file" }];
  assert.equal(matchesSearch({ attachment: fileValue }, fields, "invoice"), true, "the real filename shown in the table cell must be searchable");
  assert.equal(matchesSearch({ attachment: fileValue }, fields, "files.example.com"), false, "the raw stored URL is never shown on screen, so it must not match");
  assert.equal(matchesSearch({ attachment: fileValue }, fields, "application/pdf"), false, "the raw stored mimetype is never shown on screen, so it must not match");

  const { fieldDisplayValue } = new Function(`${parseFileFieldValueSrc}\n${fieldDisplayValueSrc}\nreturn { fieldDisplayValue };`)() as {
    fieldDisplayValue: (field: unknown, value: unknown) => string;
  };
  assert.equal(fieldDisplayValue({ type: "file" }, fileValue), "invoice.pdf", "the CSV export must show just the filename, not the raw JSON descriptor");

  const transformed = transformSync(`${isImageMimeTypeSrc}\n${parseFileFieldValueSrc}\nfunction Highlighted({ text }) { return text; }\n${entityViewJsx.match(/function Cell\(\{ field, value, relationLabel, highlightQuery, onJumpToRecord \}\) \{[\s\S]*?\n\}\n/)![0]}`, {
    loader: "jsx",
    jsxFactory: "h",
    jsxFragment: "Frag",
  }).code;
  const Cell = new Function("h", "Frag", `${transformed}\nreturn Cell;`)(
    (_type: unknown, props: Record<string, unknown> | null, ...children: unknown[]) =>
      props?.href ? { href: props.href, children } : children.length === 1 ? children[0] : children,
    Symbol("Fragment"),
  ) as (props: { field: unknown; value: unknown }) => unknown;

  const rendered = Cell({ field: { type: "file" }, value: fileValue }) as { href: string; children: unknown };
  assert.equal(rendered.href, "https://files.example.com/invoice.pdf", "the table cell must link straight to the real file, not render the raw JSON as plain text");
});

/**
 * New in this round: a file field's stored value is a JSON descriptor an
 * upload endpoint sets -- not something a CSV cell can ever supply, and
 * typing text into one would both fail to attach a real file and corrupt
 * an existing one. Mirrors the live preview's own buildImportRecords
 * ("no file to attach from a CSV cell").
 *
 * Round 746 correction: an OPTIONAL file column is still skipped per-row
 * exactly as before, but a REQUIRED one must refuse the whole import
 * upfront (same as a required, unresolvable relation field just below) --
 * not silently skip the column and let every row through, since the
 * server's own coerce() unconditionally rejects every single one of those
 * rows afterward with "Field is required". This test used to assert the
 * old, buggy behavior (zero errors, one wasted POST per row); it now
 * asserts the upfront refusal the live preview's buildImportRecords
 * already had all along.
 */
test("the exported EntityView's CSV import skips an optional file column, but refuses the whole import upfront for a required one", () => {
  const withFile: Project = {
    ...project,
    spec: {
      ...project.spec,
      entities: [
        ...project.spec.entities,
        {
          name: "Document",
          label: "Document",
          fields: [
            { name: "title", label: "Title", type: "text", required: true },
            { name: "attachment", label: "Attachment", type: "file", required: false },
          ],
        },
      ],
    },
  };
  const entityViewJsx = generateExportFiles(withFile).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;
  const buildImportRecordsSrc = entityViewJsx.match(/function buildImportRecords\(fields, rows, relatedRecords\) \{[\s\S]*?\n  return \{ records, errors \};\n\}\n/)?.[0];
  const matchesImportHeaderSrc = entityViewJsx.match(/function matchesImportHeader\([\s\S]*?\n\}\n/)?.[0];
  const fieldLabelOccurrencesSrc = entityViewJsx.match(/function fieldLabelOccurrences\(fields\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(buildImportRecordsSrc && matchesImportHeaderSrc && fieldLabelOccurrencesSrc, "expected to find buildImportRecords/matchesImportHeader/fieldLabelOccurrences in generated output");

  const ALL_ENTITIES = withFile.spec.entities;
  const { buildImportRecords } = new Function(
    "ALL_ENTITIES",
    `${matchesImportHeaderSrc}\n${fieldLabelOccurrencesSrc}\n${buildImportRecordsSrc}\nreturn { buildImportRecords };`,
  )(ALL_ENTITIES) as { buildImportRecords: (fields: unknown[], rows: string[][], relatedRecords: unknown) => { records: unknown[]; errors: string[] } };

  const fields = withFile.spec.entities.find((e) => e.name === "Document")!.fields;

  const optionalResult = buildImportRecords(fields, [["Title", "Attachment"], ["Invoice", "not-real-json-garbage"]], {});
  assert.deepEqual(optionalResult.errors, [], "an optional file column must never block the import -- there's no CSV cell that could ever satisfy it");
  assert.equal(optionalResult.records.length, 1);
  assert.equal("attachment" in optionalResult.records[0]!, false, "the file column's cell text must never be written into the record, required or not");

  const requiredFields = [fields[0]!, { ...fields[1]!, required: true }];
  const requiredResult = buildImportRecords(requiredFields, [["Title", "Attachment"], ["Invoice", "not-real-json-garbage"]], {});
  assert.deepEqual(requiredResult.records, [], "a required file field can never be satisfied from a CSV cell, so the whole import must be refused upfront");
  assert.equal(requiredResult.errors.length, 1);
  assert.match(requiredResult.errors[0]!, /required file field/);
  assert.match(requiredResult.errors[0]!, /Attachment/);
});

