/**
 * Round 984: a real bug introduced by round 980's own fix (not a
 * pre-existing gap), found by a fresh Explore survey. Mirrors the live
 * preview's own identical fix (EntityPanel.tsx) and the exported app's
 * own handleBulkUpdate/commitInlineEdit fixes just above, for the main
 * single-record Add/edit form's own handleSubmit. Drives the real
 * generated EntityView component (handleSubmit has too many closure
 * dependencies -- form, editingId, etc. -- to extract cleanly via regex
 * the way the simpler handlers above do).
 */
test("the exported EntityView's Add form refuses a non-numeric value for a 'number' field, instead of sending a doomed POST", async () => {
  const withOrder: Project = {
    ...project,
    spec: {
      ...project.spec,
      entities: [
        ...project.spec.entities,
        {
          name: "Order",
          label: "Order",
          fields: [
            { name: "client", label: "Client", type: "text", required: true },
            { name: "amount", label: "Amount", type: "number", required: false },
          ],
        },
      ],
    },
  };
  const files = generateExportFiles(withOrder);
  const dir = writeGeneratedWebComponent(files);
  const originalFetch = globalThis.fetch;
  let postCalled = false;
  globalThis.fetch = (async (input: string, init?: RequestInit): Promise<Response> => {
    const method = init?.method ?? "GET";
    if (method === "GET" && input === "/api/Order") {
      return new Response(JSON.stringify({ records: [] }), { status: 200, headers: { "content-type": "application/json" } });
    }
    if (method === "POST" && input === "/api/Order") {
      postCalled = true;
      return new Response(JSON.stringify({ record: { id: 1 } }), { status: 201 });
    }
    throw new Error(`unexpected request ${method} ${input}`);
  }) as typeof fetch;

  try {
    await withRealLocalStorage(async () => {
      const { EntityView } = await import(path.join(dir, "web", "src", "components", "EntityView.jsx"));
      const orderEntity = withOrder.spec.entities.find((e) => e.name === "Order")!;
      const props = {
        entity: orderEntity,
        highlightRecordId: null,
        onHighlightHandled: () => {},
        onJumpToRecord: () => {},
        onRecordCountChange: () => {},
      };

      const { container } = render(React.createElement(EntityView, props));
      for (let i = 0; i < 40; i++) {
        if (container.querySelector(".record-form")) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }
      const form = container.querySelector(".record-form") as HTMLFormElement;
      assert.ok(form, "expected the record form to render");

      const clientInput = form.querySelector('input[type="text"]') as HTMLInputElement;
      await act(async () => {
        fireEvent.change(clientInput, { target: { value: "Widget Co" } });
      });
      const amountInput = form.querySelector('input[inputmode="decimal"]') as HTMLInputElement;
      assert.ok(amountInput, "expected the number field's own decimal-keyboard-hint input");
      await act(async () => {
        fireEvent.change(amountInput, { target: { value: "not-a-number" } });
      });

      await act(async () => {
        fireEvent.submit(form);
      });

      assert.equal(postCalled, false, "a new Order record must never actually be created with a non-numeric amount");
      const errorEl = container.querySelector("p.error");
      assert.ok(errorEl, "expected a specific error message");
      assert.match(errorEl!.textContent ?? "", /"Amount" must be a number/, "must name the field, not the generic 'is a required field' wording");
    });
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Updated in round 980: the exported app's FieldInput had the identical
 * bug round 980 fixed in the live preview -- a "number" field's
 * <input type="number"> couldn't have a negative value typed into it
 * from empty (the native number input's own value-sanitization algorithm
 * requires at least one digit before it reports anything through
 * .value, so a lone "-" was wiped before this component's own code ever
 * ran). Mirrors the live preview's fix: a real "number" field now
 * renders as a plain text input with a decimal-friendly keyboard hint
 * instead, which also makes the previous step="any" concern moot (a text
 * input performs no native step validation at all). A relation field's
 * raw fallback number input (an always-integer, always non-negative
 * foreign key) is unaffected and keeps the native number input.
 */
test("the exported EntityView's number field input is a plain text input with a decimal keyboard hint (not a native number input), while a relation field's fallback input keeps the native number input", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const fieldInputSrc = entityViewJsx.match(/function FieldInput\(\{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(fieldInputSrc, "expected to find FieldInput in generated output");
  assert.match(
    fieldInputSrc!,
    /field\.type === "number" \|\| field\.type === "relation"[\s\S]{0,900}type=\{isPlainNumberField \? "text" : "number"\}[\s\S]{0,50}inputMode=\{isPlainNumberField \? "decimal" : undefined\}/,
    'the number/relation input branch must render a real "number" field as a plain text input with a decimal keyboard hint, keeping the relation field\'s fallback as a native number input',
  );
});

