/**
 * New in this round: the exported app's FieldInput had the identical gap
 * the live preview's own EntityPanel.tsx did -- none of the form controls
 * ever wired field.required into the real HTML `required` attribute, so
 * a required field could be left empty and submitted without any native
 * browser blocking. Confirms every non-boolean branch of the generated
 * FieldInput carries `required={field.required}`, and the boolean
 * (checkbox) branch deliberately does NOT -- an unchecked checkbox is
 * already a complete, real value, not an "empty" state to require away.
 */
test("the exported EntityView's FieldInput wires field.required into the real required attribute on every branch except boolean", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const fieldInputSrc = entityViewJsx.match(/function FieldInput\(\{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(fieldInputSrc, "expected to find FieldInput in generated output");

  // round 440 added a disabled, loading-placeholder <select> branch ahead
  // of the real, option-backed one (rendered while relatedEntityRecords
  // hasn't resolved yet) -- anchor on filteredRecords.map (round 698's own
  // client-side filter over relatedEntityRecords) to land in the real
  // branch specifically, not the loading placeholder.
  const relationSelectBranch = fieldInputSrc!.match(/field\.type === "relation" && relatedEntity\)[\s\S]*?filteredRecords\.map/)?.[0];
  assert.match(relationSelectBranch ?? "", /required=\{field\.required\}/, "the relation <select> branch must be required-wired");

  const booleanBranch = fieldInputSrc!.match(/field\.type === "boolean"[\s\S]{0,200}\}\n\s*\}/)?.[0];
  assert.doesNotMatch(booleanBranch ?? "", /required=\{field\.required\}/, "the boolean checkbox branch must NOT be required-wired");

  const enumBranch = fieldInputSrc!.match(/field\.type === "enum"[\s\S]{0,1200}/)?.[0];
  assert.match(enumBranch ?? "", /required=\{field\.required\}/, "the enum <select> branch must be required-wired");

  const longtextBranch = fieldInputSrc!.match(/field\.type === "longtext"[\s\S]{0,150}/)?.[0];
  assert.match(longtextBranch ?? "", /required=\{field\.required\}/, "the longtext <textarea> branch must be required-wired");

  const dateBranch = fieldInputSrc!.match(/field\.type === "date"[\s\S]{0,150}/)?.[0];
  assert.match(dateBranch ?? "", /required=\{field\.required\}/, "the date input branch must be required-wired");

  const numberBranch = fieldInputSrc!.match(/field\.type === "number" \|\| field\.type === "relation"[\s\S]{0,400}/)?.[0];
  assert.match(numberBranch ?? "", /required=\{field\.required\}/, "the number/relation-fallback input branch must be required-wired");

  const textBranch = fieldInputSrc!.match(/return <input id=\{id\} type="text"[\s\S]{0,100}/)?.[0];
  assert.match(textBranch ?? "", /required=\{field\.required\}/, "the plain text input fallback branch must be required-wired");
});

/**
 * New in this round: the exported app's FieldInput had no "file" branch at
 * all, so a file field fell through to the plain text fallback above --
 * letting a user type arbitrary text into a required field (satisfying the
 * HTML5 `required` check with text that was never a real file) and, worse,
 * freely overwrite an existing attachment's real JSON descriptor with
 * whatever they typed, corrupting it. There's no upload endpoint in this
 * exported app to wire a real file picker to, so the fix shows the
 * existing attachment (if any) as a plain link and nothing more -- not an
 * `<input type="text">` masquerading as something it can't actually do.
 * Runs the real generated FieldInput, extracted the same way the step/
 * required tests above do.
 */
test("the exported EntityView's FieldInput shows a file field's existing attachment as a plain link, with no editable text input that could corrupt it", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const fieldInputSrc = entityViewJsx.match(/function FieldInput\(\{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(fieldInputSrc, "expected to find FieldInput in generated output");

  const fileBranch = fieldInputSrc!.match(/if \(field\.type === "file"\) \{[\s\S]*?\n  \}\n/)?.[0];
  assert.ok(fileBranch, "expected a dedicated file branch in the generated FieldInput");
  assert.doesNotMatch(fileBranch!, /type="text"/, "a file field must never fall through to (or reuse) a free-text input");
  assert.doesNotMatch(fileBranch!, /type="file"/, "there's no upload endpoint in the exported app to wire a real file picker to");

  const parseFileFieldValueSrc = entityViewJsx.match(/function parseFileFieldValue\(value\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(parseFileFieldValueSrc, "expected to find parseFileFieldValue in generated output");

  const transformed = transformSync(`${parseFileFieldValueSrc}\nfunction FieldInput({ field, value }) {\n  const id = "test-id";\n${fileBranch}\n}`, {
    loader: "jsx",
    jsxFactory: "h",
    jsxFragment: "Frag",
  }).code;
  const FieldInput = new Function("h", "Frag", `${transformed}\nreturn FieldInput;`)(
    (type: unknown, props: Record<string, unknown> | null, ...children: unknown[]) => ({ type, props, children }),
    Symbol("Fragment"),
  ) as (props: { field: unknown; value: unknown }) => { type: unknown; props: Record<string, unknown> | null; children: unknown[] };

  const fileValue = JSON.stringify({ url: "https://files.example.com/invoice.pdf", name: "invoice.pdf", size: 1024, mimeType: "application/pdf" });
  const withFile = FieldInput({ field: { type: "file" }, value: fileValue });
  const withFileJson = JSON.stringify(withFile);
  assert.match(withFileJson, /invoice\.pdf/, "the existing attachment's real filename must still be shown");
  assert.match(withFileJson, /https:\/\/files\.example\.com\/invoice\.pdf/, "the existing attachment's real link must still be shown");

  const withoutFile = FieldInput({ field: { type: "file" }, value: "" });
  assert.doesNotMatch(JSON.stringify(withoutFile), /invoice\.pdf/, "with no current file, nothing from a previous call must leak through");
});

/**
 * Round 443: field.enumValues has no uniqueness constraint anywhere in this
 * app (and deliberately isn't given one at the shared-schema level --
 * ProductSpecSchema is append-only in practice, so tightening it would make
 * an already-stored project with this defect fail to parse from now on,
 * too high a cost for what's only a cosmetic rendering bug). The realistic
 * path for a real project to end up with a duplicate is an AI-generated
 * spec. Before this fix, every enum <select> in the exported app (same as
 * the live preview's EntityPanel.tsx) mapped enumValues straight to
 * <option> elements keyed by the raw value, so a duplicate rendered the
 * same choice twice. Extracts the real generated uniqueEnumValues helper
 * via "real generated code via new Function" (this file's own established
 * standard) and calls it directly, then confirms all three enum-rendering
 * branches (FieldInput's <select>, BoardCard's move <select>, and the
 * toolbar's filter-by-field <select>) route through it rather than mapping
 * field.enumValues/boardField.enumValues/f.enumValues directly.
 */
test("the exported app's uniqueEnumValues de-dupes real generated code, and every enum <select> branch routes through it", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const helperSrc = entityViewJsx.match(/function uniqueEnumValues\(values\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(helperSrc, "expected to find a real generated uniqueEnumValues helper");
  const uniqueEnumValues = new Function(`${helperSrc}\nreturn uniqueEnumValues;`)() as (values: string[] | undefined) => string[];
  assert.deepEqual(
    uniqueEnumValues(["new", "new", "won"]),
    ["new", "won"],
    "must dedupe while preserving first-occurrence order",
  );
  assert.deepEqual(uniqueEnumValues(undefined), [], "must tolerate a missing enumValues array, same as the original inline fallback did");

  const boardCardSrc = entityViewJsx.match(/function BoardCard\(\{[\s\S]*?\n\}\n/)?.[0];
  assert.match(
    boardCardSrc ?? "",
    /const knownBoardValues = uniqueEnumValues\(boardField\.enumValues\);/,
    "the board card's move dropdown must route boardField.enumValues through uniqueEnumValues",
  );
  assert.match(
    boardCardSrc ?? "",
    /\{boardOptionValues\.map/,
    "the board card's move dropdown must render boardOptionValues (knownBoardValues plus a stale current value, if any), not the deduped list alone",
  );

  const fieldInputSrc = entityViewJsx.match(/function FieldInput\(\{[\s\S]*?\n\}\n/)?.[0];
  const enumBranch = fieldInputSrc!.match(/field\.type === "enum"[\s\S]{0,1200}/)?.[0];
  assert.match(
    enumBranch ?? "",
    /const knownEnumValues = uniqueEnumValues\(field\.enumValues\);/,
    "the add/edit form's enum <select> must route field.enumValues through uniqueEnumValues",
  );
  assert.match(
    enumBranch ?? "",
    /\{enumOptionValues\.map/,
    "the add/edit form's enum <select> must render enumOptionValues (knownEnumValues plus a stale current value, if any), not the deduped list alone",
  );

  assert.match(
    entityViewJsx,
    /uniqueEnumValues\(f\.enumValues\)\.map/,
    "the toolbar's filter-by-field <select> must route f.enumValues through uniqueEnumValues",
  );
});

/**
 * New in this round: a record can carry a legacy enum value no longer in
 * the field's current enumValues (e.g. after an AI refine renamed the
 * field's options -- migrate.ts only ever adds columns on refine, it never
 * rewrites existing row data; this is exactly the scenario the board's own
 * "(other)" column, added in an earlier round, exists to handle without
 * dropping the record). That earlier fix never touched BoardCard's own move
 * <select> or FieldInput's add/edit-form enum <select>, both of which only
 * ever rendered <option>s for the field's current enumValues -- a
 * controlled <select> whose value matches no <option> is silently blanked
 * by the browser (selectedIndex -1), so the record's real stage/value
 * appeared as a blank selection instead of its actual stored value.
 * Extracts the real generated option-list computation for both branches
 * (same "real generated code via new Function" standard this file already
 * uses for uniqueEnumValues) and calls it directly with a stale value.
 */
test("the exported app's BoardCard move select and FieldInput's enum select both include an <option> for a stale value outside the field's current enumValues", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const helperSrc = entityViewJsx.match(/function uniqueEnumValues\(values\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(helperSrc, "expected to find a real generated uniqueEnumValues helper");

  const boardLogicSrc = entityViewJsx.match(/  const currentBoardValue = [\s\S]*?\n  const boardOptionValues = [^\n]*\n/)?.[0];
  assert.ok(boardLogicSrc, "expected to find BoardCard's real generated option-list computation");
  const computeBoardOptions = new Function(
    "record",
    "boardField",
    `${helperSrc}\n${boardLogicSrc}\nreturn boardOptionValues;`,
  ) as (record: Record<string, unknown>, boardField: { name: string; enumValues?: string[] }) => string[];

  assert.deepEqual(
    computeBoardOptions({ status: "archived" }, { name: "status", enumValues: ["new", "won"] }),
    ["archived", "new", "won"],
    "a stale value not in enumValues must get its own leading option, not be silently dropped from the select",
  );
  assert.deepEqual(
    computeBoardOptions({ status: "new" }, { name: "status", enumValues: ["new", "won"] }),
    ["new", "won"],
    "a value already in enumValues must not be duplicated",
  );
  assert.deepEqual(
    computeBoardOptions({}, { name: "status", enumValues: ["new", "won"] }),
    ["new", "won"],
    "a missing/empty value must not add a spurious blank option",
  );

  const enumLogicSrc = entityViewJsx.match(/    const currentEnumValue = [\s\S]*?\n    const enumOptionValues = [^\n]*\n/)?.[0];
  assert.ok(enumLogicSrc, "expected to find FieldInput's real generated enum option-list computation");
  const computeEnumOptions = new Function(
    "value",
    "field",
    `${helperSrc}\n${enumLogicSrc}\nreturn enumOptionValues;`,
  ) as (value: unknown, field: { enumValues?: string[] }) => string[];

  assert.deepEqual(
    computeEnumOptions("archived", { enumValues: ["new", "won"] }),
    ["archived", "new", "won"],
    "the add/edit form's enum select must offer the record's stale value too, not just the current enumValues",
  );
});

/**
 * Round 752: the test just above confirms boardOptionValues correctly
 * adds no spurious "" entry for a missing/empty value -- but that also
 * means the move <select> has literally no <option> at all matching its
 * own controlled value="" in that exact case (a record whose board field
 * is null/unset, e.g. an optional board field left blank at creation, or
 * any pre-existing row after a refine added this field as a brand-new
 * column). hasEmptyBoardOption is the real generated flag the exported
 * app's JSX uses to render a disabled "" placeholder option specifically
 * for that case, mirroring FieldInput's own enum branch, which always
 * renders one.
 */
test("the exported app's BoardCard computes hasEmptyBoardOption so its move select can render a real placeholder for a null/unset status, instead of leaving no matching <option> at all", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const hasEmptyBoardOptionSrc = entityViewJsx.match(/  const hasEmptyBoardOption = [^\n]*\n/)?.[0];
  assert.ok(hasEmptyBoardOptionSrc, "expected to find BoardCard's real generated hasEmptyBoardOption computation");
  const computeHasEmptyBoardOption = new Function(
    "record",
    "boardField",
    `const currentBoardValue = String(record[boardField.name] ?? "");\n${hasEmptyBoardOptionSrc}\nreturn hasEmptyBoardOption;`,
  ) as (record: Record<string, unknown>, boardField: { name: string }) => boolean;

  assert.equal(
    computeHasEmptyBoardOption({ status: null }, { name: "status" }),
    true,
    "a null status must flag that the move select needs its own placeholder option",
  );
  assert.equal(computeHasEmptyBoardOption({}, { name: "status" }), true, "a missing status field entirely must also flag it");
  assert.equal(
    computeHasEmptyBoardOption({ status: "new" }, { name: "status" }),
    false,
    "a real, present status value needs no placeholder -- it already gets its own matching <option>",
  );

  assert.match(
    entityViewJsx,
    /\{hasEmptyBoardOption && \(\s*<option value="" disabled>/,
    "the move select must actually render the placeholder option when hasEmptyBoardOption is true",
  );
});

/**
 * New in this round: handleToggleColumn's own "keep at least one column
 * visible" guard computed how many columns are actually visible as
 * `entity.fields.length - hiddenFields.size`. That undercounts the real
 * visible column count once hiddenFields holds a name that isn't one of
 * this entity's current fields -- e.g. a user re-running a newer export of
 * the same project in a browser that still has an older export's
 * localStorage for "forge_hidden_columns", naming a field the newer export
 * no longer has. The phantom entry gets counted as if it were hiding a real
 * column, wrongly convincing the guard that only one column is left
 * visible and refusing to let the user hide a column that was never
 * blanked out in the first place. Extracts the real generated
 * hiddenCount/visibleCount computation (same "real generated code via new
 * Function" standard this file already uses) and confirms a phantom hidden
 * name is never counted toward visibleCount.
 */
test("the exported app's handleToggleColumn never counts a stale hiddenFields entry (naming a field that no longer exists) toward its visible-column guard", () => {
  const entityViewJsx = generateExportFiles(project).find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  const visibleCountSrc = entityViewJsx.match(/    const hiddenCount = [\s\S]*?\n    const visibleCount = [^\n]*\n/)?.[0];
  assert.ok(visibleCountSrc, "expected to find handleToggleColumn's real generated visibleCount computation");
  const computeVisibleCount = new Function("entity", "hiddenFields", `${visibleCountSrc}\nreturn visibleCount;`) as (
    entity: { fields: { name: string }[] },
    hiddenFields: Set<string>,
  ) => number;

  const entity = { fields: [{ name: "name" }, { name: "status" }] };
  assert.equal(
    computeVisibleCount(entity, new Set(["stage"])),
    2,
    "a hidden name for a field that no longer exists must not be counted -- both real fields are still visible",
  );
  assert.equal(
    computeVisibleCount(entity, new Set(["status"])),
    1,
    "hiding a real field must still count normally",
  );
  assert.equal(
    computeVisibleCount(entity, new Set(["status", "stage"])),
    1,
    "a real hidden field plus a phantom one must count only the real one",
  );
});

