  assert.match(appJsx, /aria-label=\{`Move \$\{entityDisplayLabel\(e, entityTabLabelOccurrences\)\} tab earlier`\}/);
  assert.match(appJsx, /aria-label=\{`Move \$\{entityDisplayLabel\(e, entityTabLabelOccurrences\)\} tab later`\}/);
