/**
 * Mirrors the "'d' shortcut does not fire while GlobalSearch is open"
 * regression test above, against the second dialog that now shares the
 * exact same isAnyDialogOpen() guard (generalized from isSearchDialogOpen
 * in this same round): proves markDialogOpen/markDialogClosed/
 * isAnyDialogOpen genuinely work across BOTH dialogs sharing one counter,
 * not just the one the guard was originally written for. Without this,
 * pressing "d" while just reading the shortcuts cheat-sheet (focus starts
 * on its own Close button, exactly the non-input control isTypingTarget
 * alone can't catch) would silently duplicate a background row the user
 * wasn't even looking at.
 */
test("the exported EntityView's 'd' shortcut does not fire while ShortcutsPanel is open on top of the table", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const store = [
    { id: 1, name: "Acme Corp", status: "New" },
    { id: 2, name: "Globex", status: "Won" },
  ];
  const originalFetch = globalThis.fetch;
  let postCount = 0;
  globalThis.fetch = (async (input: string, init?: RequestInit): Promise<Response> => {
    const method = init?.method ?? "GET";
    if (method === "GET" && input === "/api/Customer") {
      return new Response(JSON.stringify({ records: store }), { status: 200, headers: { "content-type": "application/json" } });
    }
    if (method === "GET") {
      return new Response(JSON.stringify({ records: [] }), { status: 200, headers: { "content-type": "application/json" } });
    }
    if (method === "POST" && input === "/api/Customer") {
      postCount += 1;
      const body = JSON.parse(init!.body as string);
      const record = { id: 3, ...body };
      store.push(record);
      return new Response(JSON.stringify({ record }), { status: 201, headers: { "content-type": "application/json" } });
    }
    throw new Error(`unexpected request ${method} ${input}`);
  }) as typeof fetch;

  try {
    await withRealLocalStorage(async () => {
      const { EntityView } = await import(path.join(dir, "web", "src", "components", "EntityView.jsx"));
      const { ShortcutsPanel } = await import(path.join(dir, "web", "src", "components", "ShortcutsPanel.jsx"));
      const customerEntity = project.spec.entities.find((e) => e.name === "Customer")!;
      const props = {
        entity: customerEntity,
        highlightRecordId: null,
        onHighlightHandled: () => {},
        onJumpToRecord: () => {},
        onRecordCountChange: () => {},
      };

      const { container } = render(React.createElement(EntityView, props));
      for (let i = 0; i < 40; i++) {
        if (container.querySelectorAll("tbody tr").length === 2) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }
      assert.equal(container.querySelectorAll("tbody tr").length, 2, "expected both records to have loaded");

      await act(async () => {
        fireEvent.keyDown(window, { key: "j" });
      });
      const focused = container.querySelector(".record-row-focused") as HTMLElement;
      assert.equal(focused.getAttribute("data-record-id"), "1", "sanity check: 'j' must have focused the first row");

      const shortcutsRender = render(React.createElement(ShortcutsPanel, { onClose: () => {} }));
      assert.match(shortcutsRender.container.textContent ?? "", /Keyboard shortcuts/, "sanity check: ShortcutsPanel must actually be mounted");

      await act(async () => {
        fireEvent.keyDown(window, { key: "d" });
      });
      assert.equal(postCount, 0, "'d' must not duplicate the background row while ShortcutsPanel is open on top of it");
      assert.equal(container.querySelectorAll("tbody tr").length, 2, "no new row may appear while the shortcuts overlay is open");

      shortcutsRender.unmount();

      await act(async () => {
        fireEvent.keyDown(window, { key: "d" });
      });
      for (let i = 0; i < 40; i++) {
        if (container.querySelectorAll("tbody tr").length === 3) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }
      assert.equal(postCount, 1, "'d' must work normally again once ShortcutsPanel has closed");
      assert.equal(container.querySelectorAll("tbody tr").length, 3, "the duplicate must actually appear now that the overlay is gone");
    });
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * End-to-end App.jsx wiring: pressing "?" (guarded by isEditableEventTarget,
 * the same convention "/" already uses) opens ShortcutsPanel, the topbar
 * button next to Search does the same thing via a real click, and Escape
 * closes it -- the three ways the live preview's own App.tsx (round 629's
 * own still-open candidate until this round) makes the panel reachable.
 */
test("the exported App opens ShortcutsPanel on '?', via its own topbar button, and closes it on Escape", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: string) => {
    if (input === "/api/entity-counts") {
      return new Response(JSON.stringify({ counts: {} }), { status: 200, headers: { "content-type": "application/json" } });
    }
    return new Response(JSON.stringify({ records: [] }), { status: 200, headers: { "content-type": "application/json" } });
  }) as typeof fetch;

  try {
    await withRealLocalStorage(async () => {
      const { default: App } = await import(path.join(dir, "web", "src", "App.jsx"));
      const { container } = render(React.createElement(App));

      await act(async () => {
        fireEvent.keyDown(window, { key: "?" });
      });
      assert.ok(container.querySelector(".shortcuts-list"), "'?' must open the shortcuts panel");

      await act(async () => {
        fireEvent.keyDown(window, { key: "Escape" });
      });
      assert.equal(container.querySelector(".shortcuts-list"), null, "Escape must close the shortcuts panel");

      const shortcutsButton = Array.from(container.querySelectorAll(".search-trigger")).find((b) => b.textContent?.includes("Keyboard shortcuts")) as HTMLButtonElement;
      assert.ok(shortcutsButton, "expected a topbar button for the shortcuts panel, with the same .search-trigger styling as the Search button");
      await act(async () => {
        fireEvent.click(shortcutsButton);
      });
      assert.ok(container.querySelector(".shortcuts-list"), "clicking the topbar button must open the shortcuts panel too");
    });
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Regression test for round 655: showSearch and showShortcuts were two
 * independent booleans -- unlike the live preview's own openPanel(), which
 * is mutually exclusive among its own panels -- so pressing "?" then "/"
 * (or the reverse) stacked GlobalSearch and ShortcutsPanel on top of each
 * other instead of swapping between them. Each overlay's own
 * hideDialogBackgroundFromAssistiveTech then marked the OTHER overlay (not
 * just the real page background) inert and aria-hidden, trapping whichever
 * one was actually visible on top behind an unreachable one underneath.
 * Confirms both directions: opening Shortcuts and then pressing "/" or
 * Ctrl+K leaves Shortcuts open and never mounts GlobalSearch, and opening
 * GlobalSearch and then pressing "?" leaves GlobalSearch open and never
 * mounts Shortcuts -- in both cases exactly one `[role="dialog"]` exists at
 * a time, and Escape still closes whichever one is actually open.
 */
test("the exported App never stacks GlobalSearch and ShortcutsPanel on top of each other", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: string) => {
    if (input === "/api/entity-counts") {
      return new Response(JSON.stringify({ counts: {} }), { status: 200, headers: { "content-type": "application/json" } });
    }
    return new Response(JSON.stringify({ records: [] }), { status: 200, headers: { "content-type": "application/json" } });
  }) as typeof fetch;

  try {
    await withRealLocalStorage(async () => {
      const { default: App } = await import(path.join(dir, "web", "src", "App.jsx"));
      const { container } = render(React.createElement(App));

      // Open Shortcuts, then try both ways of opening Search on top of it.
      await act(async () => {
        fireEvent.keyDown(window, { key: "?" });
      });
      assert.ok(container.querySelector(".shortcuts-list"), "sanity check: '?' must open the shortcuts panel");

      await act(async () => {
        fireEvent.keyDown(window, { key: "/" });
      });
      assert.equal(container.querySelectorAll('[role="dialog"]').length, 1, "'/' must never stack a second dialog on top of the open shortcuts panel");
      assert.ok(container.querySelector(".shortcuts-list"), "the shortcuts panel must still be the one open");
      assert.equal(container.querySelector(".global-search-input"), null, "GlobalSearch must never have mounted underneath it");

      await act(async () => {
        fireEvent.keyDown(window, { key: "k", ctrlKey: true });
      });
      assert.equal(container.querySelectorAll('[role="dialog"]').length, 1, "Ctrl+K must never stack a second dialog on top of the open shortcuts panel either");
      assert.ok(container.querySelector(".shortcuts-list"), "the shortcuts panel must still be the one open after Ctrl+K too");

      await act(async () => {
        fireEvent.keyDown(window, { key: "Escape" });
      });
      assert.equal(container.querySelectorAll('[role="dialog"]').length, 0, "Escape must close the shortcuts panel once nothing is stacked on top of it");

      // Reverse order: open Search, then try to open Shortcuts on top of it.
      await act(async () => {
        fireEvent.keyDown(window, { key: "/" });
      });
      assert.ok(container.querySelector(".global-search-input"), "sanity check: '/' must open global search");

      await act(async () => {
        fireEvent.keyDown(window, { key: "?" });
      });
      assert.equal(container.querySelectorAll('[role="dialog"]').length, 1, "'?' must never stack the shortcuts panel on top of the open search dialog");
      assert.ok(container.querySelector(".global-search-input"), "the search dialog must still be the one open");
      assert.equal(container.querySelector(".shortcuts-list"), null, "ShortcutsPanel must never have mounted underneath it");

      await act(async () => {
        fireEvent.keyDown(window, { key: "Escape" });
      });
      assert.equal(container.querySelectorAll('[role="dialog"]').length, 0, "Escape must close the search dialog too");
    });
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * New in this round: the exported app's own GlobalSearch had the identical
 * gap the live preview's own GlobalSearchPanel.tsx did before it gained
 * Copy/Download buttons -- a cross-entity result set only ever existed on
 * screen, with no way to take it anywhere once the panel closed. Mirrors
 * apps/web/src/GlobalSearchPanel.test.ts's own real-DOM Copy/Download test:
 * confirms neither button renders before a real search has run, both
 * appear once real results exist, and clicking Copy writes the real
 * formatted results (not a placeholder) to the clipboard.
 */
test("the exported GlobalSearch's Copy/Download buttons only appear once real results exist, and Copy writes the real formatted results to the clipboard", async (t) => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: string) => {
    if (String(input).endsWith("/Customer")) {
      return { ok: true, status: 200, json: async () => ({ records: [{ id: 1, name: "Acme widget order" }] }) };
    }
    return { ok: true, status: 200, json: async () => ({ records: [] }) };
  }) as typeof fetch;

  let writtenText: string | undefined;
  Object.defineProperty(navigator, "clipboard", {
    value: { writeText: async (text: string) => void (writtenText = text) },
    configurable: true,
  });

  try {
    const { GlobalSearch } = await import(path.join(dir, "web", "src", "components", "GlobalSearch.jsx"));
    render(
      React.createElement(GlobalSearch, {
        entities: project.spec.entities,
        onClose: () => {},
        onJumpToEntity: () => {},
        onJumpToRecord: () => {},
      }),
    );

    assert.equal(
      Array.from(document.querySelectorAll("button")).some((b) => b.textContent === "Copy"),
      false,
      "no Copy button should render before any search has run",
    );

    const input = document.querySelector(".global-search-input") as HTMLInputElement;
    await act(async () => {
      fireEvent.change(input, { target: { value: "widget" } });
      fireEvent.submit(document.querySelector("form.global-search-form")!);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });

    const copyButton = Array.from(document.querySelectorAll("button")).find((b) => b.textContent === "Copy");
    const downloadButton = Array.from(document.querySelectorAll("button")).find((b) => b.textContent === "Download");
    assert.ok(copyButton, "expected a Copy button once real results exist");
    assert.ok(downloadButton, "expected a Download button once real results exist");
    assert.equal(copyButton!.getAttribute("aria-live"), "polite", "the copy button's own changing label must be announced to screen readers, not just silently change visually");
    assert.equal(copyButton!.getAttribute("aria-atomic"), "true", "the whole button's text must be re-announced, not just the changed part");

    t.mock.timers.enable({ apis: ["setTimeout"] });

    await act(async () => {
      fireEvent.click(copyButton!);
      await Promise.resolve();
      await Promise.resolve();
    });

    assert.equal(typeof writtenText, "string", "clicking Copy must actually call navigator.clipboard.writeText");
    assert.match(writtenText!, /widget/, "the copied text must include the real search query");
    assert.match(writtenText!, /Acme widget order/, "the copied text must be the real formatted results, not a placeholder");
    assert.equal(copyButton!.textContent, "Copied!", "must show the real Copied confirmation");

    act(() => {
      t.mock.timers.tick(2000);
    });
    assert.equal(copyButton!.textContent, "Copy", "must revert to the normal label once the delay elapses");
  } finally {
    t.mock.timers.reset();
    globalThis.fetch = originalFetch;
    delete (navigator as { clipboard?: unknown }).clipboard;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Regression test for a real gap found while porting -- see round 314's
 * trigger-prompt note that this was the last known gap in the
 * port-to-exported-codegen family: the exported app's own groupFieldName/
 * sortKeys/viewMode were always plain `useState` with no persistence at
 * all, unlike every other per-entity view preference this exported app
 * already remembers (hidden columns, column widths, column order, entity
 * tab order), and unlike the live preview's own groupByPreference.ts/
 * viewModePreference.ts/sortKeysPreference.ts. Extracts and runs the three
 * real generated store functions directly (not a regex proxy for their
 * logic) against a fake localStorage, mirroring this file's own
 * entity-tab-order persistence test.
 */
test("the exported EntityView's group-by/view-mode/sort-key choices are each persisted per entity via real localStorage-backed stores", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  // Round 1030: also captures migrateEntityStoreKeyCase, prepended
  // separately rather than widening storeSrc's own span to reach back to
  // it -- that span crosses the exported `computeResizedWidth` between
  // the column-widths and column-order sections, and `export` is not
  // valid inside a plain Function body ("Unexpected token 'export'").
  const migrateHelperSrc = entityViewJsx.match(/function migrateEntityStoreKeyCase\(store, entityName, writeStore\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(migrateHelperSrc, "expected to find migrateEntityStoreKeyCase in generated output");
  const storeSrc = entityViewJsx.match(/const GROUP_FIELD_STORAGE_KEY[\s\S]*?\nfunction setPersistedFieldFilters\(entityName, filters\) \{[\s\S]*?\n\}\n/)?.[0];
  assert.ok(storeSrc, "expected to find the group-field/view-mode/sort-keys/field-filters store functions in generated output");

  const fakeStorage: Record<string, string> = {};
  const {
    getPersistedGroupField,
    setPersistedGroupField,
    getPersistedViewMode,
    setPersistedViewMode,
    getPersistedSortKeys,
    setPersistedSortKeys,
    getPersistedFieldFilters,
    setPersistedFieldFilters,
  } = new Function(
    "localStorage",
    `${migrateHelperSrc}\n${storeSrc}\nreturn { getPersistedGroupField, setPersistedGroupField, getPersistedViewMode, setPersistedViewMode, getPersistedSortKeys, setPersistedSortKeys, getPersistedFieldFilters, setPersistedFieldFilters };`,
  )({
    getItem: (k: string) => fakeStorage[k] ?? null,
    setItem: (k: string, v: string) => {
      fakeStorage[k] = v;
    },
  }) as {
    getPersistedGroupField: (entityName: string) => string;
    setPersistedGroupField: (entityName: string, fieldName: string) => string;
    getPersistedViewMode: (entityName: string) => string;
    setPersistedViewMode: (entityName: string, mode: string) => string;
    getPersistedSortKeys: (entityName: string) => { field: string; direction: string }[];
    setPersistedSortKeys: (entityName: string, keys: { field: string; direction: string }[]) => { field: string; direction: string }[];
    getPersistedFieldFilters: (entityName: string) => Record<string, string>;
    setPersistedFieldFilters: (entityName: string, filters: Record<string, string>) => Record<string, string>;
  };

  // Defaults, matching the live app's own "" / "table" / [] defaults.
  assert.equal(getPersistedGroupField("Customer"), "", "no stored group field yet must default to empty (no grouping)");
  assert.equal(getPersistedViewMode("Customer"), "table", "no stored view mode yet must default to table");
  assert.deepEqual(getPersistedSortKeys("Customer"), [], "no stored sort keys yet must default to an empty array");
  assert.deepEqual(getPersistedFieldFilters("Customer"), {}, "no stored field filters yet must default to an empty object");

  // Round-trip each store, scoped by entity name.
  setPersistedGroupField("Customer", "status");
  assert.equal(getPersistedGroupField("Customer"), "status", "a stored group field must round-trip");
  setPersistedViewMode("Customer", "board");
  assert.equal(getPersistedViewMode("Customer"), "board", "a stored view mode must round-trip");
  const keys = [{ field: "name", direction: "asc" }];
  setPersistedSortKeys("Customer", keys);
  assert.deepEqual(getPersistedSortKeys("Customer"), keys, "stored sort keys must round-trip");
  setPersistedFieldFilters("Customer", { status: "New" });
  assert.deepEqual(getPersistedFieldFilters("Customer"), { status: "New" }, "stored field filters must round-trip");

  // A different entity must not see Customer's own stored choices.
  assert.equal(getPersistedGroupField("Service"), "", "a different entity must not inherit another entity's group field");
  assert.equal(getPersistedViewMode("Service"), "table", "a different entity must not inherit another entity's view mode");
  assert.deepEqual(getPersistedSortKeys("Service"), [], "a different entity must not inherit another entity's sort keys");
  assert.deepEqual(getPersistedFieldFilters("Service"), {}, "a different entity must not inherit another entity's field filters");

  // Clearing back to the default value removes the stored entry entirely
  // (mirroring the live app's own "" / "table" / [] / {} clearing
  // semantics), rather than leaving a stale, now-meaningless entry behind
  // forever.
  setPersistedGroupField("Customer", "");
  assert.equal(getPersistedGroupField("Customer"), "", "clearing the group field must round-trip back to empty");
  setPersistedViewMode("Customer", "table");
  assert.equal(getPersistedViewMode("Customer"), "table", "switching back to table view must round-trip");
  setPersistedSortKeys("Customer", []);
  assert.deepEqual(getPersistedSortKeys("Customer"), [], "clearing all sort keys must round-trip back to empty");
  setPersistedFieldFilters("Customer", { status: "" });
  assert.deepEqual(getPersistedFieldFilters("Customer"), {}, "clearing a filter back to '' must drop it from storage entirely, not persist an empty string");
});

/**
 * Round 839: ports the live Forge AI preview's own round-838 fix to this
 * exported app -- the round-838 "scope note" explicitly flagged this exact
 * port as a follow-up. getPersistedGroupField persists only the group-by
 * field NAME, with no type-tracking mechanism at all (unlike the live
 * preview, which now has both round 780's live-mount ref AND round 838's
 * own persisted-type remount check -- this exported app's frozen-at-export
 * schema never needs the live-mount half, the same reasoning round 751/780
 * used to rule out a ref here, but the cross-export reachability path
 * rounds 509/570/834 already established for sibling stores applies
 * identically: a user re-exporting after a refine retypes the grouped
 * field, reloaded against a browser still holding an older export's
 * localStorage, sees the stale field name survive unchanged while
 * groupRecordsByField's boolean branch coerces still-unconverted legacy
 * values through Boolean(...), fabricating a confidently-labeled "Yes"
 * group). Confirms the fix via two separate generated exports (simulating
 * two different exports of the same project after a refine, rather than
 * a live rerender -- this exported app's own schema can never change
 * within one mount, so the only reachable path is a fresh mount of a
 * DIFFERENT export, mirrored by two distinct generateExportFiles calls).
 */
test("the exported EntityView drops a persisted 'Group by' selection when a newer export retyped that field, instead of silently mislabeling every record", async () => {
  const customerWithEnumStatus: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [
      { name: "name", label: "Name", type: "text", required: true },
      {
        name: "status",
        label: "Status",
        type: "enum",
        required: true,
        enumValues: ["Pending", "Shipped"],
        enumLabels: { Pending: "Pending", Shipped: "Shipped" },
      },
    ],
  };
  const customerWithBooleanStatus: Entity = {
    name: "Customer",
    label: "Customers",
    fields: [
      { name: "name", label: "Name", type: "text", required: true },
      { name: "status", label: "Status", type: "boolean", required: true },
    ],
  };
  const olderExportProject: Project = { ...project, spec: { ...project.spec, entities: [customerWithEnumStatus] } };
  const newerExportProject: Project = { ...project, spec: { ...project.spec, entities: [customerWithBooleanStatus] } };
  const store = [
    { id: 1, name: "Acme Corp", status: true },
    { id: 2, name: "Globex", status: false },
  ];
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: string) => {
    if (input === "/api/Customer") {
      return new Response(JSON.stringify({ records: store }), { status: 200, headers: { "content-type": "application/json" } });
    }
    throw new Error(`unexpected request ${input}`);
  }) as typeof fetch;

  const olderDir = writeGeneratedWebComponent(generateExportFiles(olderExportProject));
  const newerDir = writeGeneratedWebComponent(generateExportFiles(newerExportProject));
  try {
    await withRealLocalStorage(async () => {
      // Simulates grouping by "status" in an OLDER export, while it was
      // still an enum -- persists the real field name AND type via the
      // real generated store functions.
      const { EntityView: OlderEntityView } = await import(path.join(olderDir, "web", "src", "components", "EntityView.jsx"));
      const olderEntity = olderExportProject.spec.entities[0];
      const olderProps = {
        entity: olderEntity,
        highlightRecordId: null,
        onHighlightHandled: () => {},
        onJumpToRecord: () => {},
        onRecordCountChange: () => {},
      };
      const older = render(React.createElement(OlderEntityView, olderProps));
      for (let i = 0; i < 40; i++) {
        if (older.container.querySelectorAll("tbody tr").length > 0) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }
      const groupBySelect = older.container.querySelector(".entity-group-by") as HTMLSelectElement;
      await act(async () => {
        fireEvent.change(groupBySelect, { target: { value: "status" } });
      });
      assert.equal(groupBySelect.value, "status", "sanity check: the older export's own grouping must have actually been set");
      older.unmount();

      // Simulates re-downloading/reloading a NEWER export of the same
      // project at the same origin, after a refine retyped "status" to
      // boolean -- a fresh dynamic import (a genuinely different
      // generated module, not a rerender of the same instance), with
      // the real browser localStorage from the older export still
      // holding the stale "status" selection.
      const { EntityView: NewerEntityView } = await import(path.join(newerDir, "web", "src", "components", "EntityView.jsx"));
      const newerEntity = newerExportProject.spec.entities[0];
      const newerProps = {
        entity: newerEntity,
        highlightRecordId: null,
        onHighlightHandled: () => {},
        onJumpToRecord: () => {},
        onRecordCountChange: () => {},
      };
      const newer = render(React.createElement(NewerEntityView, newerProps));
      for (let i = 0; i < 40; i++) {
        if (newer.container.querySelectorAll("tbody tr[data-record-id]").length === 2) break;
        await act(async () => {
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      }
      assert.equal(
        newer.container.querySelectorAll("tbody tr[data-record-id]").length,
        2,
        "expected both records to have loaded",
      );

      assert.equal(
        (newer.container.querySelector(".entity-group-by") as HTMLSelectElement).value,
        "",
        "the newer export must drop the stale 'Group by' selection, not keep pointing at the now-retyped field",
      );
      assert.doesNotMatch(
        newer.container.querySelector("table tbody")?.textContent ?? "",
        /Yes/,
        "must never show a fabricated 'Yes' group mislabeling both records from their stale enum values",
      );
    });
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(olderDir, { recursive: true, force: true });
    rmSync(newerDir, { recursive: true, force: true });
  }
});

