/**
 * New in this round: the exported app's per-entity table search box had
 * zero memory of recent queries, the same gap the live preview's own
 * EntityPanel.tsx had before entityRecentSearches.ts (round 318) -- and
 * the more impactful of the two remaining recent-searches gaps (the other,
 * Global Search's own recent-searches, is a less-used box than the
 * per-entity table every tab opens into). Extracts and *executes* the real
 * generated store functions (not a reimplementation): capped at 5, most
 * recent first, case-insensitive dedup/removal, and scoped per entity name
 * only (this single-tenant exported app has no project id to scope by,
 * unlike the live preview's own two-key (projectId, entityName) scoping).
 */
test("the exported EntityView's recent-searches store caps at 5, dedupes case-insensitively, and is scoped per entity name", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  // Round 1030: also captures migrateEntityStoreKeyCase -- see the
  // identical note on the hiddenColumns test (above, in this same file)
  // for why.
  const storeSrc = entityViewJsx.match(
    /function migrateEntityStoreKeyCase\(store, entityName, writeStore\) \{[\s\S]*?\nfunction clearEntityRecentSearches\(entityName\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(storeSrc, "expected to find the entity recent-searches store functions in generated output");

  const fakeStorage: Record<string, string> = {};
  const { getEntityRecentSearches, addEntityRecentSearch, removeEntityRecentSearch, clearEntityRecentSearches } = new Function(
    "localStorage",
    `${storeSrc}\nreturn { getEntityRecentSearches, addEntityRecentSearch, removeEntityRecentSearch, clearEntityRecentSearches };`,
  )({
    getItem: (k: string) => fakeStorage[k] ?? null,
    setItem: (k: string, v: string) => {
      fakeStorage[k] = v;
    },
  }) as {
    getEntityRecentSearches: (entityName: string) => string[];
    addEntityRecentSearch: (entityName: string, query: string) => string[];
    removeEntityRecentSearch: (entityName: string, query: string) => string[];
    clearEntityRecentSearches: (entityName: string) => void;
  };

  assert.deepEqual(getEntityRecentSearches("Customer"), [], "no stored searches yet must default to an empty array");

  addEntityRecentSearch("Customer", "acme");
  addEntityRecentSearch("Customer", "globex");
  assert.deepEqual(addEntityRecentSearch("Customer", "ACME"), ["ACME", "globex"], "re-adding case-insensitively must move it to the front (with the newly typed casing), not duplicate it");

  for (const q of ["a", "b", "c", "d", "e"]) addEntityRecentSearch("Customer", q);
  assert.deepEqual(
    getEntityRecentSearches("Customer"),
    ["e", "d", "c", "b", "a"],
    "the list must cap at 5 entries, dropping the oldest",
  );

  assert.deepEqual(removeEntityRecentSearch("Customer", "C"), ["e", "d", "b", "a"], "removal must be case-insensitive");

  assert.deepEqual(getEntityRecentSearches("Service"), [], "a different entity must not inherit Customer's own recent searches");

  clearEntityRecentSearches("Customer");
  assert.deepEqual(getEntityRecentSearches("Customer"), [], "clearing must wipe the entity's own list entirely");
});

/**
 * Round 632's finding: this store's own two siblings in the same
 * generated file -- the live preview's entityRecentSearches.ts this store
 * is explicitly modeled on, and this file's own
 * getGlobalSearchRecentSearches a few hundred lines below -- both filter
 * out any non-string entry from a stored array before using it. This
 * store's own readEntityRecentSearchesStore (pre-fix) didn't, so a
 * corrupted/foreign localStorage value (a browser extension, a manual
 * devtools edit, anything other than this app's own writes) containing a
 * non-string entry would silently survive into getEntityRecentSearches's
 * return value, then crash addEntityRecentSearch/removeEntityRecentSearch
 * the next time either runs .toLowerCase() over it -- uncaught, from
 * inside the search box's own onKeyDown handler, with no error boundary
 * around EntityView to catch it. Same corrupted-localStorage-must-not-
 * throw convention this project already fixed once by name (round 401,
 * sharedProjectSeen.ts).
 */
test("the exported EntityView's recent-searches store filters out a non-string entry instead of crashing on the next add/remove", () => {
  const files = generateExportFiles(project);
  const entityViewJsx = files.find((f) => f.path === "web/src/components/EntityView.jsx")!.content;

  // Round 1030: also captures migrateEntityStoreKeyCase -- see the
  // identical note on the hiddenColumns test (above, in this same file)
  // for why.
  const storeSrc = entityViewJsx.match(
    /function migrateEntityStoreKeyCase\(store, entityName, writeStore\) \{[\s\S]*?\nfunction clearEntityRecentSearches\(entityName\) \{[\s\S]*?\n\}\n/,
  )?.[0];
  assert.ok(storeSrc, "expected to find the entity recent-searches store functions in generated output");

  const fakeStorage: Record<string, string> = {
    forge_entity_recent_searches: JSON.stringify({ Customer: ["acme", 42, null, "globex"] }),
  };
  const { getEntityRecentSearches, addEntityRecentSearch, removeEntityRecentSearch } = new Function(
    "localStorage",
    `${storeSrc}\nreturn { getEntityRecentSearches, addEntityRecentSearch, removeEntityRecentSearch };`,
  )({
    getItem: (k: string) => fakeStorage[k] ?? null,
    setItem: (k: string, v: string) => {
      fakeStorage[k] = v;
    },
  }) as {
    getEntityRecentSearches: (entityName: string) => string[];
    addEntityRecentSearch: (entityName: string, query: string) => string[];
    removeEntityRecentSearch: (entityName: string, query: string) => string[];
  };

  assert.deepEqual(
    getEntityRecentSearches("Customer"),
    ["acme", "globex"],
    "the non-string entries must already be filtered out of a plain read, not just survive until the next write",
  );

  assert.doesNotThrow(
    () => addEntityRecentSearch("Customer", "initech"),
    "adding a new query must not throw even though the stored array originally had non-string entries",
  );
  assert.deepEqual(getEntityRecentSearches("Customer"), ["initech", "acme", "globex"]);

  fakeStorage.forge_entity_recent_searches = JSON.stringify({ Customer: ["acme", 42, "globex"] });
  assert.doesNotThrow(
    () => removeEntityRecentSearch("Customer", "acme"),
    "removing a query must not throw even when the stored array still has a non-string entry sitting next to the real ones",
  );
});

