/**
 * Round 904: mirrors GlobalSearchPanel.test.ts's own new regression test.
 * Unlike runSearch (which clears `error` at its own start), the exported
 * app's handleShowAll only ever SET `error` (round 663) and never cleared
 * it on success -- a failed "Show all" attempt left its error banner
 * showing forever, even after the user retried the exact same button and
 * it succeeded.
 */
test("the exported GlobalSearch's 'Show all' button clears a stale error banner from an earlier failed 'Show all' attempt, once retried successfully", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const originalFetch = globalThis.fetch;
  let customerCallCount = 0;
  globalThis.fetch = (async (input: string) => {
    if (String(input).endsWith("/Customer")) {
      customerCallCount += 1;
      if (customerCallCount === 2) {
        // The initial search (call 1) succeeds; this entity's own first
        // "Show all" attempt (call 2) fails.
        return { ok: false, status: 500, json: async () => ({ error: "Show all failed" }) };
      }
      const records = Array.from({ length: 7 }, (_, i) => ({ id: i + 1, name: `Widget item ${i + 1}` }));
      return { ok: true, status: 200, json: async () => ({ records }) };
    }
    return { ok: true, status: 200, json: async () => ({ records: [] }) };
  }) as typeof fetch;

  try {
    const { GlobalSearch } = await import(path.join(dir, "web", "src", "components", "GlobalSearch.jsx"));
    const { container } = render(
      React.createElement(GlobalSearch, {
        entities: project.spec.entities,
        onClose: () => {},
        onJumpToEntity: () => {},
        onJumpToRecord: () => {},
      }),
    );

    const input = container.querySelector(".global-search-input") as HTMLInputElement;
    await act(async () => {
      fireEvent.change(input, { target: { value: "widget" } });
      fireEvent.submit(container.querySelector("form.global-search-form")!);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });
    assert.equal(container.querySelectorAll(".global-search-hit-button").length, 5, "expected the default 5-row sample");

    const showAllButton = container.querySelector(".global-search-show-all") as HTMLButtonElement | null;
    assert.ok(showAllButton, "expected a 'Show all' button for the original 7-match count");

    await act(async () => {
      fireEvent.click(showAllButton!);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });
    assert.ok(container.querySelector(".error"), "expected the failed 'Show all' attempt's error banner to render");

    await act(async () => {
      fireEvent.click(container.querySelector(".global-search-show-all") as HTMLButtonElement);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });

    assert.equal(container.querySelectorAll(".global-search-hit-button").length, 7, "expected every real match once the retried 'Show all' succeeds");
    // Checked as a boolean, not a bare assert.equal(node, null) -- see the
    // round-556 test above for why.
    assert.equal(
      container.querySelector(".error") === null,
      true,
      "the stale error banner must not survive a later, successful retry of the exact same 'Show all' action",
    );
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 519's finding: mirrors GlobalSearchPanel.test.ts's own new
 * regression test. Unlike the handlers that submit a fresh query (both of
 * which clear expandedSamples first), the exported app's Retry button
 * called runSearch directly -- so a "Show all" expansion made before a
 * partial-failure Retry survived the retry's own fresh fetch, leaving a
 * stale sample on screen instead of the newly re-fetched data.
 */
test("the exported GlobalSearch's Retry button clears a stale 'Show all' expansion instead of keeping outdated samples", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const originalFetch = globalThis.fetch;
  let customerCallCount = 0;
  let serviceCallCount = 0;
  globalThis.fetch = (async (input: string) => {
    if (String(input).endsWith("/Customer")) {
      customerCallCount += 1;
      // Call 1 is the initial search, call 2 is "Show all"'s own re-fetch
      // -- both still see the original 7 matches. Call 3 is the Retry's
      // fresh fetch, where real-world data has since changed.
      if (customerCallCount <= 2) {
        const records = Array.from({ length: 7 }, (_, i) => ({ id: i + 1, name: `Widget item ${i + 1}` }));
        return { ok: true, status: 200, json: async () => ({ records }) };
      }
      return {
        ok: true,
        status: 200,
        json: async () => ({ records: [{ id: 101, name: "Widget item FRESH-A" }, { id: 102, name: "Widget item FRESH-B" }] }),
      };
    }
    serviceCallCount += 1;
    if (serviceCallCount === 1) {
      return { ok: false, status: 500, json: async () => ({ error: "Server exploded" }) };
    }
    return { ok: true, status: 200, json: async () => ({ records: [] }) };
  }) as typeof fetch;

  try {
    const { GlobalSearch } = await import(path.join(dir, "web", "src", "components", "GlobalSearch.jsx"));
    const { container } = render(
      React.createElement(GlobalSearch, {
        entities: project.spec.entities,
        onClose: () => {},
        onJumpToEntity: () => {},
        onJumpToRecord: () => {},
      }),
    );

    const input = container.querySelector(".global-search-input") as HTMLInputElement;
    await act(async () => {
      fireEvent.change(input, { target: { value: "widget" } });
      fireEvent.submit(container.querySelector("form.global-search-form")!);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });

    // Partial failure: Customer's 7 matches show (capped at a 5-row
    // sample) alongside the error+Retry row from Service's failure.
    assert.ok(container.querySelector(".error-retry-row") !== null, "expected the error+Retry row from Service's failure");
    assert.equal(container.querySelectorAll(".global-search-hit-button").length, 5, "expected the default 5-row sample");

    const showAllButton = container.querySelector(".global-search-show-all") as HTMLButtonElement;
    assert.ok(showAllButton, "expected a 'Show all' button for Customer's 7 matches");
    await act(async () => {
      fireEvent.click(showAllButton);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });
    assert.equal(container.querySelectorAll(".global-search-hit-button").length, 7, "expected the full 7-record 'Show all' sample before retrying");

    const retryButton = container.querySelector(".error-retry-row button") as HTMLButtonElement;
    await act(async () => {
      fireEvent.click(retryButton);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });

    assert.equal(container.querySelector(".error-retry-row"), null, "the error+Retry row must disappear once both entities succeed");
    assert.equal(container.querySelectorAll(".global-search-hit-button").length, 2, "Retry must drop the stale 7-record expansion and show the fresh 2-record sample");
    assert.match(container.textContent ?? "", /FRESH-A/);
    assert.match(container.textContent ?? "", /FRESH-B/);
    assert.doesNotMatch(container.textContent ?? "", /Widget item 7/, "the stale pre-retry sample must not survive the retry");
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

/**
 * Round 815's finding: the exported GlobalSearch bound "Show all"/Copy/
 * Download to the live, still-editable `query` state instead of a frozen
 * snapshot of the query that actually produced the results on screen --
 * the exact staleness bug the live preview's own GlobalSearchPanel.tsx
 * already guards against with its own separate `highlightQuery` state (set
 * only once a search actually completes), which this exported duplicate
 * never got. Submits "widget" (7 real matches, so a real "Show all" button
 * appears), then edits the search box to "zzz" (which matches nothing)
 * WITHOUT resubmitting -- `query` now holds "zzz" while the 7 widget
 * results are still the ones on screen. Confirms "Show all" still expands
 * to all 7 real "widget" matches (not the 0 a live "zzz" filter would
 * produce), and that Copy's own report header still names "widget" (the
 * search that actually produced its listed rows), not the edited-but-
 * unsubmitted "zzz".
 */
test("the exported GlobalSearch's 'Show all'/Copy stay locked to the search that produced the results on screen, not a since-edited-but-unsubmitted search box", async () => {
  const files = generateExportFiles(project);
  const dir = writeGeneratedWebComponent(files);
  const customerRecords = Array.from({ length: 7 }, (_, i) => ({ id: i + 1, name: `Widget item ${i + 1}` }));
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: string) => {
    if (String(input).endsWith("/Customer")) {
      return { ok: true, status: 200, json: async () => ({ records: customerRecords }) };
    }
    return { ok: true, status: 200, json: async () => ({ records: [] }) };
  }) as typeof fetch;

  let writtenText: string | undefined;
  Object.defineProperty(navigator, "clipboard", {
    value: { writeText: async (text: string) => void (writtenText = text) },
    configurable: true,
  });

  try {
    const { GlobalSearch } = await import(path.join(dir, "web", "src", "components", "GlobalSearch.jsx"));
    const { container } = render(
      React.createElement(GlobalSearch, {
        entities: project.spec.entities,
        onClose: () => {},
        onJumpToEntity: () => {},
        onJumpToRecord: () => {},
      }),
    );

    const input = container.querySelector(".global-search-input") as HTMLInputElement;
    await act(async () => {
      fireEvent.change(input, { target: { value: "widget" } });
      fireEvent.submit(container.querySelector("form.global-search-form")!);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });
    assert.equal(container.querySelectorAll(".global-search-hit-button").length, 5, "expected the default 5-row sample before expanding");

    // Edit the box WITHOUT resubmitting -- the 7 "widget" results on
    // screen are unaffected, but the live query state now says "zzz".
    await act(async () => {
      fireEvent.change(input, { target: { value: "zzz" } });
    });
    assert.equal(input.value, "zzz", "the box itself must show the edit (this is a real, ordinary thing a user can do)");
    assert.equal(
      container.querySelectorAll(".global-search-hit-button").length,
      5,
      "editing the box alone, without resubmitting, must not change what's already on screen",
    );

    const showAllButton = container.querySelector(".global-search-show-all") as HTMLButtonElement;
    assert.ok(showAllButton, "expected a real 'Show all' button when more matches exist than the sample shows");
    await act(async () => {
      fireEvent.click(showAllButton);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });
    assert.equal(
      container.querySelectorAll(".global-search-hit-button").length,
      7,
      "'Show all' must expand to every real 'widget' match -- the search that's actually on screen -- not re-filter against the edited-but-unsubmitted 'zzz'",
    );

    const copyButton = Array.from(container.querySelectorAll("button")).find((b) => b.textContent === "Copy") as HTMLButtonElement;
    await act(async () => {
      fireEvent.click(copyButton);
      await Promise.resolve();
    });
    assert.match(
      writtenText ?? "",
      /"widget"/,
      "the Copy report's own header must still name the search that actually produced its listed rows ('widget'), not the edited-but-unsubmitted 'zzz'",
    );
    assert.doesNotMatch(writtenText ?? "", /"zzz"/, "the Copy report must never embed the live, unsubmitted box text instead of the real search");
  } finally {
    globalThis.fetch = originalFetch;
    cleanup();
    rmSync(dir, { recursive: true, force: true });
  }
});

